(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uk"] = {"ui":{"skip":"Перейти до вмісту","back":"← Назад до AI-gile","lang.button":"Мова: {name}","lang.dialog":"Обери мову","lang.search":"Шукати мову","lang.none":"Жодна мова не підходить","lang.notYet":"{name} ще не перекладено","theme.aria":"Змінити тему: світла, темна чи чорна","theme.toLight":"Перемкнути на світлу тему","theme.toDark":"Перемкнути на темну тему","theme.toBlack":"Перемкнути на чорну тему (справжній чорний, добре для екранів OLED)","words.underline":"Підкреслити ці слова на сторінці","words.underlineHelp":"Наведи курсор або торкнися слова з крапковим підкресленням, щоб побачити, що воно означає.","words.col.todo":"Картки, обрані на зараз: команда візьметься за них далі.","words.col.doing":"Один ШІ просто зараз працює над цією карткою.","words.col.review":"Один ШІ виконав роботу; інший перевіряє її, перш ніж вона дійде до тебе.","words.col.verify":"Чекає на тебе: спробуй і скажи, чи працює.","words.col.team":"Твої нотатки або відповіді, що чекають, поки команда їх підхопить.","words.col.done":"Завершено й прийнято.","index.title":"AI-gile: твоя ШІ-команда розробників на одній дошці","index.description":"AI-gile — це канбан-дошка для команд, що пишуть код разом зі ШІ. Вони працюють, поки ти спиш, а тобі лишається одна коротка купка: що вирішити, що перевірити і що прийняти.","hero.logoAlt":"Значок дошки AI-gile","hero.h1.html":"Твоя ШІ-команда розробників на одній&nbsp;дошці.","hero.alpha":"🐣 Закрита пре-альфа","hero.alphaTitle":"Рано й недороблено: дякуємо, що пробуєш!","hero.lede":"Вони працюють, поки ти спиш. Зранку на тебе чекає коротка купка: кілька запитань, кілька речей на перевірку, один-два фіолетові діаманти. Клацни, прийми й повертайся до кави.","dl.windows":"Застосунок для Windows","dl.browser":"Запустити в браузері","dl.messenger":"📱 Messenger для телефона","dl.soon":"Скоро","dl.notify":"🔔 Сповісти, коли відкриється","dl.notifySmall":"Альфа або бета","hero.secondary":"Agile, але команді ніколи не потрібна кава на стендапі. (Стендапи вони все одно проводять.)","pitch.h2":"AI-gile стількома словами, скількома захочеш","pitch.lede":"Обери довжину: від одного слова до 144. Кожна довжина — окремий опис, написаний саме під цей розмір. Тягни повзунок або користуйся стрілками.","pitch.rangeLabel":"Довжина в словах","pitch.dice":"🎲 інший варіант","pitch.words.one":"{n} слово","pitch.words.other":"{n} слова","pitch.letters.one":"{n} літера","pitch.letters.other":"{n} літери","pitch.chars.one":"{n} символ","pitch.chars.other":"{n} символу","count.line.html.one":"{n} картка на дошці просто зараз","count.line.html.other":"{n} картки на дошці просто зараз","people.humans.html.one":"👥 {n} людина","people.humans.html.other":"👥 {n} людей","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агентів","people.working.html.one":"⚡ {n} у роботі просто зараз","people.working.html.other":"⚡ {n} у роботі просто зараз","pre.title":"AI-gile: тут щось будується","pre.description":"Тут щось будується: дошка, на якій ШІ-команди будують те, що ти просиш, і навчають тебе дорогою. Поки що закрита пре-альфа з друзями.","pre.h1":"Тут щось будується. 🤫","pre.line":"Дошка, на якій ШІ-команди будують те, що ти просиш, і навчають тебе дорогою. Поки що закрита пре-альфа з друзями.","pre.btn":"🔔 Сповісти, коли відкриється","pre.peek":"За склом: справжня дошка, наживо. Кожна картка — кольорова смужка.","pre.peekFake":"За склом: так виглядає дошка в роботі.","pre.night":"🌙 Нічний вартовий за старшого · 😴 людина відпочиває","features.aria":"Що він робить","f.pile.h":"Одна купка для тебе","f.pile.html":"<b>Для тебе</b> збирає все, що чекає на тебе в усіх проєктах: запитання, речі на перевірку, завдання, які може зробити лише людина. Твоя черга показує, що далі і скільки це займе.","f.sleep.h":"Команди, що працюють, поки ти спиш","f.sleep.p":"У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до картки, і команда прокинеться, зробить роботу й поверне її з кроками, які зрозуміє навіть невиспана людина.","f.tester.h":"Спершу перевіряє ШІ-тестувальник","f.tester.p":"Перш ніж щось дійде до тебе, тестувальник проходить кроки в копії застосунку й показує, що побачив, зі скриншотом. Перегляни ті, що пройшли, і прийми одним клацанням.","f.proof.h":"Докази, а не обіцянки","f.proof.p":"Кожна передача показує, що змінилося: файли, різницю, скриншоти. Не треба відкривати кожен застосунок, щоб дізнатися, чи все готово.","f.chat.h":"Спілкуйся зі своїми лідами","f.chat.p":"Бічна панель у стилі Discord: по значку на проєкт, фіолетові діаманти там, де потрібен ти. Напиши ліду ідею, і він перетворить її на картки та план з кнопкою ✅ Почати.","f.tidy.h":"Сам тримає лад","f.tidy.p":"Схожі картки зливаються в одну, заплутані назви виправляються, а перевірка токенів тримає код легким. Менше перемикань і менше думок.","f.private.h":"Твоє, на твоєму комп'ютері","f.private.li1":"Дошка працює на твоїй машині й відповідає лише тобі.","f.private.li2":"Приватні повідомлення між людьми наскрізно зашифровані.","f.private.li3":"Жодних акаунтів, трекерів і кукі.","f.lang.h":"Твоєю мовою","f.lang.p":"Понад 120 мов: від нідерландської, валлійської та японської до піратської, мови Йоди й клінгонської, зі швидким поверненням до англійської для фахових термінів.","f.service.h":"Від ідеї до справжнього сервісу","f.service.p":"Створив щось із ШІ, і цим уже користуються люди? Познач це як сервіс, і дошка допоможе добре його вести: перевірки доступності, публічна сторінка статусу, інциденти з розбором, зміни, яким потрібне Go, резервні копії, які перевіряють щодня. Довідка пояснює кожен крок, коли ти до нього доходиш.","msgr.h2":"AI-gile Messenger: твоя команда в кишені","msgr.p1":"Спілкуйся зі своєю AI-командою, не відкриваючи дошку. Пиши лідам своїх проєктів і друзям, переглядай кроки тестування картки й відповідай на них, усе з телефона.","msgr.p2":"Щоб під'єднати, відскануй QR-код на своїй дошці. Уперше? Привітний демо-чат усе покаже.","msgr.when":"Спершу Android, потім вебверсія для телефонів та iPhone.","msgr.who":"Лід твого проєкту","msgr.b1":"Виправлення темної теми готове. Надіслати кроки тестування?","msgr.b2":"Так, будь ласка!","msgr.b3":"1. Відкрий Налаштування. 2. Вибери Темна. Усе виглядає як слід?","tl.aria":"Часова шкала від першої розмови до дорожньої карти","tl.h2":"Від першої розмови до того, що далі","tl.lede":"Справжні дати й час, у твоєму часовому поясі. Після сьогодні — це план, без обіцяних дат.","tl.today":"Сьогодні","tl.planned":"заплановано","tl.doing":"у роботі","tl.cards.one":"{n} картка","tl.cards.other":"{n} картки","join.h2":"Долучайся","join.lede":"AI-gile будують бородатий дивак з AuDHD і кількома битвами за психічне здоров’я — і дуже багато терплячих агентів. Поки що він приватний, у закритій альфі з друзями. Хочеш спробувати, коли він відкриється?","join.btn":"Записати свій інтерес","join.small":"Ми напишемо тобі листа, і більше нічого","footer.tag":"AI-gile. Без трекерів, без кукі, без кави на стендапі.","footer.licence":"Бізнес-ліцензія","footer.status":"Статус","footer.privacy":"Що ми зберігаємо","footer.thanks":"Дзвінки завдяки ChilledChat","form.sending":"Надсилаємо…","form.failed":"Не вийшло: спробуй пізніше.","form.offline":"Не вдалося зв'язатися з AI-gile: спробуй пізніше.","form.keep":"Ми використовуємо це лише для відповіді тобі, а потім видаляємо. Жодних трекерів, жодних кукі.","form.keepLink":"Що ми зберігаємо","interest.title":"AI-gile: скажіть мені, коли відкриється альфа","interest.description":"Залиш свою пошту, щоб дізнатися, коли відкриється закрита альфа чи бета AI-gile.","interest.h1":"🔔 Сповісти, коли відкриється","interest.lede":"AI-gile у закритій пре-альфі. Залиш пошту, і ми напишемо один раз, коли для тебе знайдеться місце.","interest.email":"Твоя пошта","interest.which":"Яке тестування?","interest.alpha":"Закрита альфа: рання, сира, багато змін","interest.beta":"Бета: стабільніша, пізніше","interest.both":"Будь-яке, що з'явиться першим","interest.submit":"Додайте мене до списку","interest.thanks":"Дякуємо! Ти в списку.","licence.title":"AI-gile: бізнес-ліцензія","licence.description":"Користуєшся AI-gile у своїй справі? Подай заявку на безкоштовну бізнес-ліцензію.","licence.h1":"📜 Бізнес-ліцензія","licence.lede":"Користуєшся AI-gile на роботі? Розкажи, хто ти й чим займаєшся. Якщо це приносить трохи добра, ліцензія безкоштовна.","licence.company":"Компанія","licence.website":"Вебсайт","licence.what":"Чим ти займаєшся","licence.how":"Чим це допомагає світові","licence.email":"Пошта","licence.submit":"Подати заявку","licence.thanks":"Дякуємо! Ми відповімо на пошту.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Усе тихо","status.intro":"Чи працює AI-gile просто зараз? Ця сторінка кожні 5 хвилин перевіряє сайт, спільний доступ до дошок, дзвінки та завантаження.","status.up":"Працює (відповів за {ms} мс)","status.slow":"Не відповів на останню перевірку, пробуємо ще","status.down":"Не працює: не відповів на дві останні перевірки","status.svc.web":"Сайт","status.svc.web.offers":"Цей сайт: що таке AI-gile, і форма «Сповісти, коли відкриється»","status.svc.boards":"Спільний доступ до дошок","status.svc.boards.offers":"Публічні дошки, повідомлення між друзями та запрошення","status.svc.calls":"Дзвінки","status.svc.calls.offers":"Голос, відео й демонстрація екрана в AI-gile","status.svc.download":"Завантаження","status.svc.download.offers":"Інсталятор для Windows і посилання-запрошення","status.checking":"Перевіряємо…","status.offline":"Зараз не вдається зв'язатися зі службою статусу (пробуємо ще)","status.updated":"оновлено {ago}","status.justNow":"щойно","status.min":"{n} хв тому","status.hours":"{n} год тому","status.days":"{n} дн. тому","privacy.title":"AI-gile: що ми зберігаємо","privacy.h1":"Що ми зберігаємо","privacy.lede":"Коротко: лише те, що ти нам надсилаєш, і ненадовго.","privacy.only":"Лише те, що ти нам надсилаєш: те, що ти вводиш у форму, наприклад свою пошту. Більше нічого про тебе.","privacy.sealed":"Усе запечатується, тож наш сервер не може цього прочитати: у твоєму браузері ще до відправлення (у старішому браузері одразу після надходження). Відкрити це може лише наша власна дошка.","privacy.server":"Це видаляється із сервера, щойно потрапляє на нашу дошку. Усе, що залишилося там через 30 днів, однаково видаляється.","privacy.board":"Ми зберігаємо це на нашій дошці лише доти, доки не відповімо тобі, а потім видаляємо й там.","privacy.none":"Жодних трекерів, кукі чи аналітики.","privacy.local":"Твоя мова та вибір світлої чи темної теми залишаються у твоєму браузері. Нам їх ніколи не надсилають.","privacy.ask":"Хочеш, щоб це зникло раніше? Просто відповідай на наш лист і напиши про це.","live.h2":"Дивіться, як це будується, наживо","live.caption":"Кожна картка прихована: ви бачите форму роботи, а не слова.","live.watching.one":"наживо: дивиться {n}","live.watching.other":"наживо: дивляться {n}","live.last.now":"Останню картку переміщено щойно","live.last.min.one":"Останню картку переміщено {n} хв тому","live.last.min.other":"Останню картку переміщено {n} хв тому","live.last.hour.one":"Останню картку переміщено {n} год тому","live.last.hour.other":"Останню картку переміщено {n} год тому","live.last.day.one":"Останню картку переміщено {n} дн. тому","live.last.day.other":"Останню картку переміщено {n} дн. тому","live.offline":"Жива дошка трохи перепочиває. Заходьте знову згодом.","live.cols":"Беклог|До виконання|У роботі|Команда перевіряє|Тобі на тест|Для команди|Готово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слів","pitch.letters.few":"{n} літери","pitch.letters.many":"{n} літер","pitch.chars.few":"{n} символи","pitch.chars.many":"{n} символів","count.line.html.few":"{n} картки на дошці просто зараз","count.line.html.many":"{n} карток на дошці просто зараз","tl.cards.few":"{n} картки","tl.cards.many":"{n} карток"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делеговано."]},{"n":2,"texts":["Канбан роботів.","Агенти, впорядковані.","Ідеї збудовано."]},{"n":3,"texts":["Канбан для роботів.","Ідеї стають функціями.","Безкоштовний канбан агентів."]},{"n":5,"texts":["Канбан-дошка, яку ведуть агенти.","Ти пишеш картки. Агенти будують.","Безкоштовно, локально, перевірено, трохи безглуздо."]},{"n":8,"texts":["Безкоштовна канбан-дошка, де замість людей працюють ШІ-агенти.","Напиши ідею. Агенти збудують. Ти приймеш.","Agile для однієї людини й багатьох терплячих роботів."]},{"n":13,"texts":["Канбан-дошка на твоєму комп'ютері, де картки беруть у роботу ШІ-агенти.","Напиши ідею. Команда агентів її збудує, а тестувальник усе перевірить. Ти лише приймаєш.","Безкоштовно, без акаунтів і трекерів: дошка, трохи роботів і ти за головного."]},{"n":21,"texts":["AI-gile — це канбан-дошка для роботи з ШІ-агентами, що пишуть код. Вони беруть картки в роботу, а ти їх перевіряєш і приймаєш.","У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до будь-якої картки, і команда береться до роботи.","Безкоштовна особиста дошка завдань на твоєму власному комп'ютері. Працюють там роботи, а казати остаточне «так» будеш ти."]},{"n":34,"texts":["Ти кладеш ідеї на дошку. Команда ШІ-агентів перетворює їх на робочі функції, перевіряє й повертає тобі з кроками для спроби. Нічого не вважається готовим, доки ти цього не скажеш.","AI-gile — це саморобна канбан-дошка, яку Rich збудував із великою допомогою агентів, якими вона тепер керує. Вона безкоштовна, працює на твоєму комп'ютері й призначена для друзів, а не на продаж.","Уяви звичайну канбан-дошку з колонками від Беклогу до Готово, тільки картки тут беруть у роботу ШІ-агенти. Вони звітують про хід справи, питають, коли застрягли, і завжди чекають твого схвалення."]},{"n":55,"texts":["AI-gile — це канбан-дошка, де команда складається зі ШІ-агентів. У кожного проєкту є лід, який планує роботу, і помічники, які її виконують. Коли функція готова, ШІ-тестувальник пробує її й робить скриншот, а потім вона потрапляє до твоєї купки. Прийми її або напиши коментар, і вони переробять.","Усе почалося як спосіб однієї людини стежити за багатьма сеансами ШІ-кодування одночасно, а потім виросло в справжню дошку. Вона працює на твоїй машині, не вимагає акаунта й не має трекерів. Безкоштовна для друзів і всіх допитливих. Вона ще й недороблена, тож чекай шорсткостей і зрідка сюрпризів.","Ось чесна версія. Ідеї все одно маєш мати ти, і результати все одно маєш перевіряти ти. А AI-gile робить усе між цим: тримає картки впорядкованими, будить потрібного агента, коли ти коментуєш, показує, що саме змінилося, і збирає все це для тебе в одну коротку купку."]},{"n":89,"texts":["AI-gile — це безкоштовна канбан-дошка, яку ти запускаєш на власному комп'ютері. Замість людей у кожного проєкту є команда ШІ-агентів: лід, що перетворює твої ідеї на картки та план, і помічники, що беруть картки за пріоритетом. Коли щось збудовано, ШІ-тестувальник проходить кроки перевірки й показує тобі, що побачив. Потім усе чекає в одній купці з назвою «Для тебе». Ти приймаєш або коментуєш, і команда пробує ще раз. Без тебе нічого не потрапляє в «Готово».","Є кілька речей, яких ти можеш не чекати. Нічна варта поповнює колонку «До виконання», поки ти спиш, і вибирає картки, яким не потрібна твоя відповідь. Лічильник токенів показує, скільки агенти витратили сьогодні й цього тижня, а режим «Без токенів» велить їм зупинитися. Можна писати друзям, і приватні повідомлення наскрізно зашифровані. Дошка говорить приблизно 120 мовами, зокрема нідерландською, фламандською, піратською та клінгонською. Це не коштує ні копійки, і ніхто не намагається тобі це продати.","AI-gile — невеликий особистий проєкт, а не компанія. Rich хотів доглядати кілька проєктів зі ШІ-кодуванням, не відкриваючи щоразу кожен застосунок, тож разом з агентами збудував для цього дошку, а потім нею ж збудував решту себе. Вона в закритій пре-альфі, тобто здебільшого працює, але лише для жменьки друзів. Немає ні сторінки з цінами, ні розсилки, ні плану зростання. Якщо все це звучить корисно, можеш попроситися спробувати, щойно вона трохи відкриється для інших охочих."]},{"n":144,"texts":["AI-gile — це канбан-дошка для однієї людини й багатьох ШІ-агентів. Вона працює на твоєму власному комп'ютері й повністю безкоштовна. Ти додаєш проєкти, і кожен отримує ліда та невелику команду. Ти спілкуєшся з лідом, трохи як у Discord, і описуєш ідею; лід перетворює її на картки та план, а потім чекає, поки ти натиснеш «Почати». Команда проходить картки за пріоритетом, користуючись простим командним рядком, створеним для мовних моделей. Перш ніж щось повернеться до тебе, ШІ-тестувальник проходить усі кроки в копії застосунку й додає до них скриншот. Готова робота потрапляє до твоєї купки разом зі зміненими файлами та різницею. Ти приймаєш її або залишаєш коментар, і команда прокидається та пробує знову. Лише ти можеш перемістити картку в колонку «Готово».","День з AI-gile, приблизно. Увечері ти залишаєш кілька коментарів: ця кнопка не на місці, той список варто відсортувати, а чи можна додати темну тему. Ти йдеш спати. Агенти читають коментарі, вносять зміни, перевіряють їх і повертають тобі. Якщо «До виконання» порожніє, нічна варта наповнює його з беклогу картками, яким не потрібна твоя відповідь. Зранку на тебе чекає одна коротка купка: кілька запитань і кілька речей на спробу, кожна з кроками, які зрозуміє навіть сонна людина, і зі скриншотом, де все працює. Ти клацаєш, приймаєш добре, а решту відправляєш назад. Лічильник токенів показує, скільки це все з'їло, а режим «Без токенів» є для ощадливих тижнів. Потім ти снідаєш, і в цьому агенти поки що не допоможуть.","Спершу про те, чим AI-gile не є. Це не стартап, не товар на продаж, і ніхто не збирає твої дані. Це безкоштовна дошка, що працює на твоєму комп'ютері, без акаунтів, трекерів і кукі. А є вона єдиним охайним місцем, де видно всі проєкти зі ШІ-кодуванням одразу: команда агентів робить картки, а рішення ухвалюєш ти. Вона зливає схожі картки, виправляє заплутані назви й стежить, наскільки легким лишається код. Вона говорить приблизно 120 мовами, від нідерландської та фламандської до піратської й клінгонської. Друзі можуть писати одне одному приватно й зашифровано. Її збудували Rich і дуже багато терплячих агентів, здебільшого користуючись нею самою. Вона в закритій пре-альфі, тож подекуди шорстка. Якщо звучить цікаво, попроси чемно, і, можливо, потрапиш раніше."]}],"quips":{"1":"Одне слово. Сміливо. Можливо, занадто сміливо.","3":"Три слова. Вже чесніше за більшість сторінок продуктів.","8":"Вісім слів. Усе одно коротше за стендап.","21":"До речі, довжини — це story points. А що ж іще.","55":"П'ятдесят п'ять слів. Поки ти читав, дві картки встигли завершити.","144":"Це найдовший варіант. 233 немає. Агенти пішли спати."}},"timeline":{"first-idea.name":"Перша ідея","first-idea.line":"Найперша розмова, коли коду ще не існувало.","first-board.name":"Перша дошка","first-board.line":"Дошка, що стежить за власною розробкою: картки, колонки, перетягування, проєкти.","team-roles.name":"Команда й ролі","team-roles.line":"Профілі агентів, шаблони команд, простори й хто що робить.","install.name":"Встановлення й релізи","install.line":"Zip, який друг може встановити, самооновлення, канали й відкат.","usage-saver.name":"Заощадження ресурсу","usage-saver.line":"Міряти вартість запусків, тримати код легким, берегти свій ліміт.","friends.name":"Друзі й спільний доступ","friends.line":"Приватні повідомлення, зашифрований ретранслятор, запрошення, ролі й спільні проєкти.","languages.name":"Мови","languages.line":"Кожен екранний текст у мовному файлі, спершу нідерландська й фламандська.","ai-tester.name":"ШІ-тестувальник","ai-tester.line":"Тестувальник першим перевіряє кожну передачу й показує, що побачив.","website.name":"Вебсайт","website.line":"aigile.lol, тизер і ця часова шкала.","streaming.name":"Чат і стримінг","streaming.line":"Discord, Twitch, OBS, режим стримера, GIF-и й емодзі.","no-ai.name":"Версія без ШІ","no-ai.line":"Дошка для тих, хто пише код без ШІ, і публічні дошки.","night-watch.name":"Нічна варта","night-watch.line":"Вартовий і Scrum Master тримають команди в роботі, поки ти спиш.","p-more.name":"Усе інше","p-more.line":"Менші ідеї, що чекають своєї черги.","p-android.name":"Телефон і Android","p-android.line":"Доступ до дошки з телефона, а потім рідний застосунок для Android.","p-release.name":"Альфа й далі","p-release.line":"Закрита альфа, жива сторінка, потім бета.","p-languages.name":"Більше мов","p-languages.line":"130 мов і режим занурення для тих, хто вчить мову.","p-engines.name":"Більше ШІ-рушіїв","p-engines.line":"Обирай Claude, Codex, Gemini, Copilot або Cursor для кожного агента.","p-pro.name":"Професійна практика","p-pro.line":"Мітки ризику, ворота злиття, картки інцидентів і запобіжники.","p-self.name":"Турбота про тебе","p-self.line":"Режим втоми, нагадування про догляд за собою і 4:20.","p-servers.name":"Сервери й масштаб","p-servers.line":"Глобальні налаштування сервера, ролі й планування зростання.","p-livestream.name":"Додатки для стримінгу","p-livestream.line":"Чат Twitch, власні емодзі й публічний перегляд наживо."},"words":{"button":"📖 Фахові терміни","h":"📖 Слова простими словами","intro":"Безкоштовне навчання простою мовою: кожне слово, яке тобі трапиться, від першої ідеї до послуги, на яку покладаються люди, а дорогою Agile, розробка, безпека й робота зі ШІ.","search":"Шукати слово…","none":"Такого слова немає.","close":"Закрити","count":{"one":"{count} слово","other":"{count} слів"},"groups":[{"id":"idea","name":"💡 Ідея й дослідження"},{"id":"plan","name":"🗺️ Планування роботи"},{"id":"agile","name":"🔁 Гнучкі способи роботи"},{"id":"build","name":"🛠️ Створення"},{"id":"test","name":"🧪 Тестування і якість"},{"id":"change","name":"🔀 Безпечні зміни"},{"id":"run","name":"🛎️ Робота сервісу"},{"id":"sec","name":"🔒 Безпека й приватність"},{"id":"ai","name":"🤖 Робота зі ШІ"},{"id":"money","name":"💰 Гроші й ліцензії"}],"list":[{"id":"discovery","g":"idea","word":"Дослідження (Discovery)","text":"Ранній етап, коли з'ясовують, яку проблему варто розв'язувати і для кого, ще до того, як щось почали робити.","also":["discovery","фаза дослідження","етап дослідження","етапу дослідження","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Формулювання проблеми","text":"Одне-два речення про те, у кого проблема, у чому вона і чому важлива, щоб усі цілилися в одне й те саме.","also":["формулювання проблеми","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Користувач","text":"Людина, яка користується тим, що ти створюєш. Заради її потреб і робиться робота.","also":["користувачі","користувача","користувачів","користувачам","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Зацікавлена сторона","text":"Будь-хто, кому не байдуже, чим закінчиться робота, або на кого вона впливає: ті, хто за неї платить, користується нею чи підтримує її.","also":["зацікавлені сторони","зацікавленої сторони","зацікавлених сторін","стейкхолдер","стейкхолдери","стейкхолдерів","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Персона","text":"Вигадана, але реалістична людина, яка уособлює один тип користувачів, щоб команда могла спитати: «Чи легким це здасться Сему?»","also":["персони","персону","персон","persona","personas"]},{"id":"userresearch","g":"idea","word":"Дослідження користувачів","text":"Розмови зі справжніми людьми й спостереження за ними, щоб дізнатися, що їм потрібно, а не гадати.","also":["дослідження користувачів","інтерв'ю з користувачами","user research","user interviews"]},{"id":"journey","g":"idea","word":"Шлях користувача","text":"Кроки, які людина проходить, щоб чогось досягти: від першого знайомства до результату, зокрема й поза твоїм продуктом. Якщо намалювати шлях, видно, де людина застрягає.","also":["шляхи користувача","шляху користувача","шлях клієнта","шляху клієнта","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Больова точка","text":"Те, що сьогодні дратує людей або сповільнює їх. Хороші продукти прибирають больові точки.","also":["больові точки","больову точку","больових точок","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Припущення","text":"Те, у що віриш, але що ще не перевірено. Якщо записати припущення, буде видно, що перевіряти насамперед.","also":["припущення","припущень","припущенням","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Гіпотеза","text":"Найкраще припущення, яке ти збираєшся перевірити, разом із тим, що очікуєш побачити, наприклад: «люди зареєструються, якщо перший місяць безкоштовний».","also":["гіпотези","гіпотезу","гіпотез","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Експеримент","text":"Невелика запланована перевірка, чи працює ідея, перш ніж ставити на неї багато.","also":["експерименти","експерименту","експериментів","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC, перевірка концепції)","text":"Швидка чорнова спроба зрозуміти, чи може ідея взагалі спрацювати. Коли відповідь отримано, її зазвичай викидають.","also":["PoC","proof of concept","перевірка концепції","перевірки концепції","пруф оф концепт"]},{"id":"prototype","g":"idea","word":"Прототип","text":"Рання модель продукту, часто це просто картинки, по яких можна клікати, щоб перевірити ідею на людях, перш ніж робити все як слід.","also":["прототипи","прототипу","прототипів","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Вайрфрейм","text":"Простий начерк екрана, що показує, що де стоїть, без кольорів і справжнього вмісту.","also":["вайрфрейми","вайрфрейму","вайрфреймів","схема екрана","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Макет","text":"Докладна картинка того, як виглядатиме екран, зі справжніми кольорами й текстом, але поки що нічого не працює.","also":["макети","макету","макетів","мокап","мокапи","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Бізнес-кейс","text":"Доводи на користь проєкту: скільки він коштує, що приносить чи заощаджує і які в ньому ризики.","also":["бізнес-кейси","бізнес-кейсу","бізнес-обґрунтування","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Здійсненність","text":"Чи можна це справді зробити й підтримувати з тим часом, грошима й вміннями, які в тебе є.","also":["здійсненності","виконуваність","реалістичність","feasibility"]},{"id":"outcome","g":"idea","word":"Результат для людей (Outcome)","text":"Зміна на краще для людей, якої ти хочеш досягти, наприклад менше пропущених візитів. Вона важливіша за обсяг зробленого.","also":["результати для людей","ефект","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Напрацювання (Output)","text":"Те, що робить команда, наприклад новий екран чи звіт. Саме по собі те, що це зроблено, ще не означає, що комусь стало краще.","also":["напрацювання","результат роботи","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Метрика успіху","text":"Число, яке показує, чи зробила робота те, заради чого її затівали, наприклад: більше людей доводять замовлення до кінця.","also":["метрики успіху","метрик успіху","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Ключовий показник ефективності (KPI)","text":"Важливе число, за яким стежиш, щоб розуміти, чи все йде добре, наприклад кількість реєстрацій на тиждень.","also":["KPI","КПЕ","ключові показники","ключових показників","key performance indicator","KPIs"]},{"id":"okr","g":"idea","word":"Цілі та ключові результати (OKR)","text":"Спосіб ставити цілі: ціль каже, чого ти хочеш, а кілька ключових результатів — це числа, які показують, що мети досягнуто.","also":["OKR","OKRs","ОКР","цілі й ключові результати"]},{"id":"product","g":"plan","word":"Продукт","text":"Те, що створюють і підтримують для користувачів: застосунок, сайт чи інструмент.","also":["продукти","продукту","продуктів","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Бачення продукту","text":"Коротка заява про те, кому допомагає продукт і куди він рухається в довгостроковій перспективі.","also":["продуктове бачення","vision statement","product vision"]},{"id":"po","g":"plan","word":"Власник продукту (PO)","text":"Людина, яка вирішує, що робити і в якому порядку, щоб команда завжди займалася найважливішим. В AI-gile це ти.","also":["PO","власника продукту","product owner","product owners","продакт-овнер","продакт-овнера"]},{"id":"pm","g":"plan","word":"Менеджер продукту (PM)","text":"Людина, яка відповідає за напрям продукту: які проблеми він розв'язує, для кого і навіщо. PM може означати й менеджера проєкту, тож уточнюй, про кого мова.","also":["PM","продакт-менеджер","продакт-менеджера","менеджера продукту","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Менеджер проєкту","text":"Людина, яка стежить, щоб проєкт вкладався в терміни й бюджет, і відстежує, хто що робить і до якого часу.","also":["менеджера проєкту","проджект-менеджер","проджект-менеджера","керівник проєкту","керівника проєкту","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Дорожня карта","text":"Приблизний план того, що буде в найближчі місяці, по черзі. Вона показує напрям, а не точні дати, і змінюється, поки ти дізнаєшся нове.","also":["дорожні карти","дорожньої карти","роудмап","роадмап","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Віха","text":"Точка в проєкті, яку варто відзначити, наприклад «перша версія запущена» чи «100 користувачів».","also":["віхи","віху","віх","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Мінімально життєздатний продукт (MVP)","text":"Найменша версія продукту, яка все ж корисна справжнім людям, щоб вчитися в них якомога раніше.","also":["MVP","MVPs","minimum viable product","МВП","мінімально життєздатного продукту"]},{"id":"requirement","g":"plan","word":"Вимога","text":"Те, що готовий продукт має робити або чим має бути.","also":["вимоги","вимогу","вимог","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Обсяг робіт (Scope)","text":"Що входить у роботу і, не менш важливо, що в неї не входить.","also":["обсяг робіт","обсягу робіт","межі проєкту","скоуп","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Розповзання обсягу (Scope creep)","text":"Коли в роботу потроху додається дедалі більше, а про зайвий час і гроші ніхто не домовлявся, і через це вона ніяк не закінчується.","also":["розповзання обсягу","розповзання вимог","scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Функція","text":"Одна річ, яку продукт уміє робити для людей, наприклад «скинути пароль».","also":["функції","функцію","функцій","фіча","фічі","фічу","фіч","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Епік","text":"Великий шмат роботи, завеликий, щоб зробити його за один раз, тож його ділять на менші картки.","also":["епіки","епіку","епіків","epic","epics"]},{"id":"story","g":"plan","word":"Користувацька історія","text":"Невелика робота, описана з боку користувача: «Як покупець, я хочу зберегти кошик, щоб закінчити пізніше». З неї починається розмова про те, що робити.","also":["користувацькі історії","користувацької історії","юзер-сторі","user story","user stories"]},{"id":"ac","g":"plan","word":"Критерії приймання (AC)","text":"Перевірки, які картка має пройти, щоб вважатися готовою; їх погоджують до початку роботи, наприклад: «кошик на місці після виходу й повторного входу».","also":["AC","критерії приймання","критеріїв приймання","критерії приймання","acceptance criteria"]},{"id":"task","g":"plan","word":"Завдання","text":"Одна справа, яку треба зробити, часто це невеликий крок більшої історії.","also":["завдань","завданням","таска","таски","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Тікет","text":"Ще одне слово для картки: одна робота чи одне прохання, за яким стежать від початку до кінця.","also":["тікети","тікету","тікетів","ticket","tickets"]},{"id":"priority","g":"plan","word":"Пріоритет","text":"Наскільки щось важливе чи термінове порівняно з усім іншим, щоб найважливіше робилося першим.","also":["пріоритети","пріоритету","пріоритетів","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Розстановка пріоритетів","text":"Вибудовування роботи за важливістю. Один зі способів — MoSCoW: Must have (обов'язково), Should have (бажано), Could have (можна), Won't have (не цього разу).","also":["пріоритизація","пріоритизації","розстановки пріоритетів","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Оцінка","text":"Приблизна здогадка, наскільки велика робота або скільки вона забере. Це здогадка, а не обіцянка.","also":["оцінки","оцінку","оцінок","оцінювання","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points (бали історії)","text":"Спосіб прикинути розмір роботи, порівнюючи картки одна з одною («приблизно вдвічі більша за ту»), а не в годинах. Порівнювати за ними команди не можна.","also":["стори-пойнти","сторіпоінти","стори-пойнтів","бали історії","story point","story points"]},{"id":"tshirt","g":"plan","word":"Оцінка в розмірах футболок","text":"Оцінка розміру роботи як S, M, L або XL. Швидко й достатньо добре для раннього планування.","also":["розміри футболок","розмірів футболок","T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Покер планування","text":"Гра для оцінювання: усі одночасно показують карту з розміром, а потім ті, хто назвав найбільший і найменший, пояснюють чому.","also":["покер планування","покеру планування","Planning poker","Scrum poker","скрам-покер"]},{"id":"dependency","g":"plan","word":"Залежність","text":"Коли одна робота не може початися чи закінчитися, доки не зроблено іншу.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Блокер","text":"Усе, що просто зараз заважає роботі рухатися вперед, наприклад відсутня відповідь чи зламаний інструмент.","also":["блокери","блокера","блокерів","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Дедлайн","text":"Дата, до якої щось має бути закінчене.","also":["дедлайни","дедлайну","дедлайнів","крайній термін","крайнього терміну","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Результат роботи (Deliverable)","text":"Щось конкретне, що робота створює й передає, наприклад працююча сторінка чи звіт.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Прогноз","text":"Передбачення того, що, найімовірніше, станеться, наприклад коли робота буде готова, на основі того, що відомо на сьогодні.","also":["прогнози","прогнозу","прогнозів","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Метрика","text":"Усе, що ти вимірюєш і відстежуєш із часом, наприклад кількість відвідувань сторінки чи скільки часу йде на виправлення.","also":["метрики","метрику","метрик","metric","metrics"]},{"id":"feedback","g":"plan","word":"Зворотний зв'язок","text":"Що люди кажуть про твою роботу, добре й погане. Отримувати його рано й часто — серце Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Беклог","text":"Список очікування з ідей і роботи, яку ще не заплановано, найважливіше нагорі. Доки вона не перейде в «До виконання», над нею ніхто не працює."},{"id":"sprint","g":"agile","word":"Спринт","text":"Короткий, чітко обмежений відрізок роботи (часто один-два тижні, але не більше місяця) з ціллю та погодженим набором карток, які треба закінчити.","also":["спринти","спринтів","спринту","sprint","sprints"]},{"id":"standup","g":"agile","word":"Стендап","text":"Швидка щоденна звірка: що зробив кожен учасник команди, що робитиме далі і що йому заважає. У Scrum її називають щоденним скрамом.","also":["стендапи","стендапу","стендапів","standup","stand-ups","daily scrum","daily stand-up","щоденний скрам","щоденного скраму"]},{"id":"kanban","g":"agile","word":"Канбан","text":"Спосіб роботи, за якого картки рухаються стовпцями дошки (наприклад, До виконання, У роботі, Готово), а команда обмежує, скільки в роботі одночасно, щоб робота не стояла."},{"id":"wip","g":"agile","word":"WIP-ліміт","text":"WIP — скорочення від work in progress (робота в процесі). WIP-ліміт — найбільша кількість карток, яку може вміщати стовпець одночасно, щоб команда закінчувала справи, перш ніж починати нові.","also":["WIP","ліміт WIP"]},{"id":"dod","g":"agile","word":"Визначення «Зроблено»","text":"Короткий чекліст команди про те, що означає «готово», наприклад перевірено й пояснено, перш ніж картку передадуть тобі. Його близнюк, визначення «Готово до роботи», каже, коли картка достатньо зрозуміла, щоб почати.","also":["Definition of Ready","DoD","DoR","визначення «Готово до роботи»","визначення «Зроблено»","критерії готовності до роботи"]},{"id":"retro","g":"agile","word":"Ретро","text":"Регулярний погляд назад на те, як працює команда, щоб домовитися про одну-дві речі, які наступного разу зробити краще. Скорочення від «ретроспектива». В AI-gile ретро пропонує зміну в способах роботи команди, а ти кажеш Go або Ще ні.","also":["ретроспектива","ретроспективи","retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Рій","text":"Усі на палубу: багато людей кидають іншу роботу й разом лагодять одну термінову справу, доки її не розв'язано. В AI-gile кожна команда допомагає одному проєкту, а решта проєктів тим часом чекає.","also":["роєм","усі на палубу","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"У Scrum — людина, яка допомагає команді добре працювати: прибирає те, що їй заважає, тримає зустрічі в руслі й навчає добрих звичок, нікому не наказуючи. В AI-gile Lead Scrum Master помічає застряглі картки, підганяє команди й нагадує тобі, що чекає, у всіх проєктах.","also":["Lead Scrum Master","скрам-майстер"]},{"id":"agile","g":"agile","word":"Agile (гнучка розробка)","text":"Спосіб працювати невеликими кроками: зроби трохи, часто показуй справжні результати, вчися з того, що кажуть люди, і змінюй план по ходу справи, а не плануй усе наперед.","also":["ейджайл","аджайл","гнучка розробка","гнучкої розробки","гнучкі методології","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Маніфест Agile","text":"Коротка заява, написана 2001 року людьми, які роблять програми. У ній люди, працюючий результат, тісна робота із замовниками й готовність до змін стоять вище за важкі плани й папери.","also":["маніфесту Agile","Agile Manifesto","Manifesto for Agile Software Development","гнучкий маніфест"]},{"id":"waterfall","g":"agile","word":"Водоспад (Waterfall)","text":"Старий спосіб роботи: спершу спланувати все, потім усе побудувати, потім усе перевірити, етап за етапом. Змінювати щось пізно важко й дорого.","also":["каскадна модель","каскадної моделі","водоспадна модель","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Ітерація","text":"Одне коло: зробити щось, перевірити й покращити. Робота за Agile — це ланцюжок таких кіл, а спринт — один з їхніх видів.","also":["ітерації","ітерацію","ітерацій","iteration","iterations"]},{"id":"increment","g":"agile","word":"Інкремент","text":"Новий працюючий шматок, доданий у продукт за спринт чи коло роботи, який поєднується з тим, що вже було.","also":["інкременти","інкременту","інкрементів","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum (Скрам)","text":"Популярний спосіб працювати за Agile: невелика команда працює короткими спринтами до цілі, має наперед визначені ролі й кілька регулярних зустрічей, щоб планувати, перевіряти й покращувати."},{"id":"scrumteam","g":"agile","word":"Scrum-команда","text":"Невелика група, яка виконує роботу в Scrum: власник продукту, Scrum-майстер і розробники.","also":["скрам-команда","скрам-команди","Scrum-команди","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Події Scrum","text":"Регулярні зустрічі в Scrum: планування спринту, щоденний скрам, огляд спринту й ретро. Багато хто називає їх церемоніями.","also":["події Scrum","подій Scrum","церемонії","церемоній","церемонії Scrum","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Планування спринту","text":"Зустріч на початку спринту, на якій команда домовляється, навіщо потрібен цей спринт, які картки брати і з чого почати.","also":["планування спринту","зустріч із планування","Sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Ціль спринту","text":"Одне речення про те, заради чого цей спринт. Дрібні завдання по ходу справи можуть змінюватися, аби ціль була досягнута.","also":["цілі спринту","ціль спринту","мета спринту","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Беклог спринту","text":"Картки, обрані для поточного спринту, разом із планом команди, як їх зробити.","also":["беклоги спринту","беклогу спринту","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Беклог продукту","text":"Повний упорядкований список усього, що можна зробити для продукту, найважливіше нагорі. Він постійно змінюється, поки ти дізнаєшся нове.","also":["продуктовий беклог","беклогу продукту","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Ціль продукту","text":"Більший результат, до якого рухається продукт; він допомагає команді обирати, що робити далі.","also":["цілі продукту","мета продукту","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Уточнення беклогу","text":"Регулярний перегляд беклогу: навести лад, розбити, впорядкувати й доповнити картки деталями, щоб їх можна було брати в роботу. Ще це називають грумінгом беклогу.","also":["уточнення беклогу","грумінг беклогу","грумінг","грумінгу","рефайнмент","backlog grooming","refinement","backlog refinement"]},{"id":"sprintreview","g":"agile","word":"Огляд спринту","text":"Зустріч наприкінці спринту, на якій команда показує, що встигла зробити, і слухає, що думають люди, щоб вирішити, що далі.","also":["рев'ю спринту","огляду спринту","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Демо","text":"Показ готової роботи наживо, у дії, тим, хто про неї просив.","also":["демонстрація","демонстрації","демо-показ","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Таймбокс","text":"Фіксована кількість часу на щось. Коли вона закінчується, ти зупиняєшся, навіть якщо зроблено не все.","also":["таймбокси","таймбоксу","timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Швидкість команди (Velocity)","text":"Скільки роботи команда зазвичай встигає закінчити за спринт; за цим числом планують, скільки брати наступного разу. Це не оцінка того, наскільки старанно люди працюють.","also":["велосіті","швидкості команди","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Ємність команди (Capacity)","text":"Скільки роботи команда може взяти на себе за період, з урахуванням відпусток та інших справ.","noTip":1},{"id":"burndown","g":"agile","word":"Діаграма згоряння (Burndown)","text":"Графік роботи, що залишилася в спринті, який іде вниз день за днем. Якщо лінія стоїть рівно, щось застрягло.","also":["берндаун","діаграма згоряння","діаграми згоряння","burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Діаграма накопичення (Burnup)","text":"Графік готової роботи, що зростає з часом, поруч із загальним планом, щоб бачити, коли ти дійдеш до мети.","also":["бернап","діаграми накопичення","burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Канбан-дошка","text":"Сама дошка: стовпець для кожного етапу роботи, а картки рухаються зліва направо.","also":["дошка Kanban","канбан-дошки","канбан-дошку","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Система витягування (Pull)","text":"Спосіб роботи, за якого нова робота починається лише тоді, коли в когось з'явилося місце її взяти, а не звалюється на того, у кого й так повно справ.","also":["pull-система","pull-системи","системи витягування","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Потік","text":"Наскільки гладко робота рухається дошкою. Хороший потік — це коли картки йдуть далі, а не накопичуються.","also":["потік роботи","потоку","потоку роботи","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Час виконання (Lead time)","text":"Скільки минає часу від того, як хтось попросив про щось, до того, як це зроблено.","also":["лід-тайм","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Час циклу (Cycle time)","text":"Скільки часу займає картка з моменту, коли робота над нею справді почалася, до того, як вона готова.","also":["цикл-тайм","часу циклу","cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Пропускна здатність (Throughput)","text":"Скільки карток закінчується за тиждень або за будь-який інший відрізок часу.","also":["пропускної здатності","трупут","throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Вузьке місце","text":"Той етап, де робота накопичується й гальмує все, що за ним, як вузьке горлечко пляшки.","also":["вузькі місця","вузького місця","вузьких місць","пляшкове горлечко","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Доріжка (Swimlane)","text":"Рядок упоперек дошки, де зібрані картки одного виду, наприклад термінові або картки однієї команди.","also":["свімлейн","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (ощадливість)","text":"Спосіб працювати, за якого прибирають втрати (усе, що не допомагає клієнтові) і підтримують потік роботи."},{"id":"waste","g":"agile","word":"Втрати","text":"У Lean — усе, що потребує зусиль, але не допомагає клієнтові: очікування, переробки чи створення того, чим ніхто не користується.","noTip":1},{"id":"kaizen","g":"agile","word":"Безперервне вдосконалення","text":"Потроху ставати кращими весь час завдяки невеликим регулярним змінам, а потім перевіряти, чи вони допомогли. Ретро — один зі способів. Ще це називають кайдзен.","also":["кайдзен","безперервного вдосконалення","постійне вдосконалення","kaizen"]},{"id":"selforg","g":"agile","word":"Самоорганізована команда","text":"Команда, яка сама вирішує, як виконувати роботу, а не отримує вказівки крок за кроком.","also":["самоорганізація","самоорганізованої команди","самоорганізовані команди","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Крос-функціональна команда","text":"Команда, яка має всі вміння, щоб довести роботу до кінця сама: дизайн, розробку й тестування.","also":["кросфункціональна команда","крос-функціональної команди","крос-функціональні команди","cross-functional"]},{"id":"spike","g":"agile","word":"Спайк (Spike)","text":"Коротке дослідження з обмеженням за часом, щоб відповісти на запитання, перш ніж братися за справжню роботу.","also":["спайки","спайку","дослідницьке завдання","spike","spikes"]},{"id":"rework","g":"agile","word":"Переробка","text":"Коли роботу роблять заново, бо з першого разу вийшло не так.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Масштабований Agile (SAFe)","text":"Способи застосовувати Agile в багатьох командах великої організації. SAFe (Scaled Agile Framework) — один із найвідоміших прикладів.","also":["scaled Agile","масштабування Agile","масштабованого Agile"]},{"id":"repo","g":"build","word":"Репозиторій","text":"Папка проєкту з кодом і повною історією комітів. Вона може лежати на твоєму комп'ютері, на GitHub або і там, і там.","also":["репо","repo","repository"]},{"id":"branch","g":"build","word":"Гілка","text":"Окрема лінія роботи в коді, щоб можна було вносити зміни, не чіпаючи основну версію.","also":["гілки","branch","branches"]},{"id":"commit","g":"build","word":"Коміт","text":"Збережений знімок коду з короткою приміткою про те, що змінилося. До нього завжди можна повернутися.","also":["коміти","комітів","commit","commits"]},{"id":"push","g":"build","word":"Пуш","text":"Надсилання твоїх збережених знімків (комітів) з цього комп'ютера до спільної копії онлайн, наприклад на GitHub, щоб вони були збережені й інші могли їх отримати."},{"id":"merge","g":"build","word":"Мерж","text":"Злиття змін однієї гілки в іншу, зазвичай назад в основну версію."},{"id":"pr","g":"build","word":"Пул-реквест","text":"Прохання перевірити зміни гілки й злити їх в основну версію. На деяких сайтах це називають merge request.","also":["PR","PRs","merge request","пул-реквести","пул-реквесту","пул-реквестів","мерж-реквест"]},{"id":"refactor","g":"build","word":"Рефакторинг","text":"Наведення ладу в коді без зміни того, що він робить: менші файли, зрозуміліші назви, менше повторів."},{"id":"bug","g":"build","word":"Баг","text":"Щось, що не працює так, як має.","also":["баги","бага","багів","bug","bugs"]},{"id":"peerreview","g":"build","word":"Перевірка колегами","text":"Друга пара очей: хтось інший, не автор, перевіряє роботу, перш ніж вона дійде до тебе, тож менше помилок проскакує. В AI-gile кожну картку перевіряє інший ШІ.","also":["рев'ю","код-рев'ю","peer review","code review"]},{"id":"code","g":"build","word":"Код","text":"Записані інструкції, що кажуть комп'ютеру, що робити. Ще це називають вихідним кодом.","also":["коду","кодом","вихідний код","вихідного коду","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Мова програмування","text":"Мова, якою пишуть код, наприклад JavaScript, Python чи Java. Для різних завдань підходять різні.","also":["мови програмування","мову програмування","мов програмування","programming language","programming languages"]},{"id":"developer","g":"build","word":"Розробник (dev)","text":"Людина, яка пише й змінює код. Її ще називають програмістом або інженером-програмістом.","also":["розробники","розробника","розробників","програміст","програмісти","програміста","девелопер","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Програмне забезпечення (ПЗ)","text":"Програми, що працюють на комп'ютерах і телефонах, на відміну від самих пристроїв (заліза).","noTip":1},{"id":"app","g":"build","word":"Застосунок","text":"Програма, якою люди користуються, щоб щось зробити, на телефоні, комп'ютері чи в браузері.","also":["застосунки","застосунку","застосунків","додаток","додатки","додатка","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Вебзастосунок","text":"Застосунок, що працює в браузері, тож нічого встановлювати не потрібно.","also":["вебзастосунки","вебзастосунку","веб-додаток","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Фронтенд","text":"Частина застосунку, яку ти бачиш і на яку натискаєш: екрани, кнопки й слова, часто просто в браузері.","also":["фронтенду","клієнтська частина","клієнтської частини","front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Бекенд","text":"Закулісна частина застосунку, яка зберігає дані й робить роботу, коли ти на щось натискаєш, наприклад перевіряє пароль.","also":["бекенду","серверна частина","серверної частини","back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Фулстек","text":"Робота і над фронтендом, і над бекендом.","also":["фулстек-розробник","фулстеки","full stack","full-stack"]},{"id":"ui","g":"build","word":"Інтерфейс користувача (UI)","text":"Те, що людина бачить і використовує на екрані: розташування, кнопки, меню й текст.","also":["UI","інтерфейсу користувача","user interface"]},{"id":"ux","g":"build","word":"Досвід користувача (UX)","text":"Яке це відчуття — користуватися чимось: легко, зрозуміло й приємно чи заплутано й повільно.","also":["UX","досвіду користувача","користувацький досвід","юзабіліті","user experience"]},{"id":"accessibility","g":"build","word":"Доступність (a11y)","text":"Робити так, щоб продуктом могли користуватися всі, зокрема ті, хто погано бачить, не може користуватися мишею або користується програмою зчитування з екрана.","also":["a11y","універсальний доступ","accessibility"]},{"id":"responsive","g":"build","word":"Адаптивний дизайн","text":"Робити сторінки такими, щоб вони добре виглядали й працювали на будь-якому екрані, від телефона до великого монітора.","also":["адаптивна верстка","адаптивного дизайну","адаптивність","responsive design"]},{"id":"designsys","g":"build","word":"Дизайн-система","text":"Спільний набір кольорів, шрифтів, кнопок і правил, щоб кожен екран виглядав і поводився однаково.","also":["дизайн-системи","дизайн-систему","дизайн-систем","design system","design systems"]},{"id":"architecture","g":"build","word":"Архітектура","text":"Загальна будова системи: з яких головних частин вона складається і як вони спілкуються між собою."},{"id":"database","g":"build","word":"База даних (БД)","text":"Упорядковане сховище інформації, як дуже потужна таблиця, яку застосунок може читати й змінювати.","also":["БД","бази даних","базу даних","баз даних","database","databases","DB"]},{"id":"schema","g":"build","word":"Схема бази даних","text":"Будова бази даних: які в ній є таблиці з інформацією і що лежить у кожній.","also":["схему бази даних","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Скорочення від «мова структурованих запитів»: нею просять багато баз даних видати інформацію або змінити її.","also":["Structured Query Language","мова запитів","мови запитів"]},{"id":"data","g":"build","word":"Дані","text":"Інформація, яку зберігає комп'ютер, наприклад імена, замовлення чи налаштування.","also":["даних","набір даних","набори даних","датасет","датасети","dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Сервер","text":"Комп'ютер, який завжди ввімкнений і відповідає на запити інших комп'ютерів, наприклад віддає тобі вебсторінку, коли ти її відкриваєш.","also":["сервери","сервера","серверів","сервері","server","servers"]},{"id":"client","g":"build","word":"Клієнт","text":"Сторона, яка щось просить у сервера, зазвичай твій браузер чи застосунок. У бізнесі так ще називають просто покупця.","also":["клієнти","клієнта","клієнтів","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Скорочення від «програмний інтерфейс застосунку»: готове меню запитів, з якими одна програма може звернутися до іншої, наприклад спитати в служби погоди прогноз на сьогодні.","also":["АПІ","APIs","application programming interface","інтерфейс програмування","програмний інтерфейс"]},{"id":"endpoint","g":"build","word":"Ендпоінт","text":"Один пункт у меню API: вебадреса, до якої програма може звернутися, щоб щось отримати чи надіслати.","also":["ендпоінти","ендпоінту","кінцева точка","кінцеві точки","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Інтеграція","text":"З'єднання двох систем, щоб вони працювали разом, наприклад коли твій магазин сам надсилає замовлення в бухгалтерську програму.","also":["інтеграції","інтеграцію","інтеграцій","integration","integrations"]},{"id":"webhook","g":"build","word":"Вебхук","text":"Повідомлення, яке одна система сама надсилає іншій у ту мить, коли щось сталося, наприклад «платіж отримано».","also":["вебхуки","вебхука","вебхуків","webhook","webhooks"]},{"id":"library","g":"build","word":"Бібліотека","text":"Готовий код, який написав хтось інший і який можна використати повторно, а не писати з нуля.","also":["бібліотеки","бібліотеку","бібліотек","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Фреймворк","text":"Готовий каркас для створення застосунку, який багато в чому визначає, як улаштований код, як каркас будинку, який ти заповнюєш.","also":["фреймворки","фреймворку","фреймворків","framework","frameworks"]},{"id":"sdk","g":"build","word":"Набір для розробки (SDK)","text":"Коробка з інструментами, кодом і прикладами для створення програм під одну платформу чи службу.","also":["SDK","SDKs","СДК","набір для розробки","набору для розробки"]},{"id":"softdep","g":"build","word":"Програмна залежність","text":"Бібліотека чи інструмент, без яких твій код не працює. Тримати їх оновленими важливо для безпеки.","also":["програмні залежності","програмної залежності","залежності коду","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Пакет","text":"Набір готового коду, який можна встановити й використовувати в проєкті.","also":["пакети","пакета","пакету","пакетів","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Менеджер пакетів","text":"Інструмент, який завантажує й оновлює пакети, від яких залежить твій код. npm — один із найпоширеніших.","also":["менеджери пакетів","менеджера пакетів","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Найпоширеніший інструмент для зберігання історії змін коду у вигляді комітів і гілок."},{"id":"github","g":"build","word":"GitHub","text":"Сайт, на якому зберігаються репозиторії Git, щоб команди могли ділитися кодом, перевіряти зміни й стежити за роботою."},{"id":"vcs","g":"build","word":"Система контролю версій","text":"Зберігання повної історії кожної зміни файлів, щоб бачити, хто що змінив, і за потреби повернутися назад. Git робить саме це.","also":["контроль версій","контролю версій","системи контролю версій","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Клонування","text":"Створення власної повної копії репозиторію разом з історією на твоєму комп'ютері.","also":["клонувати","клон","клонування репозиторію","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (отримати зміни)","text":"Завантаження на твій комп'ютер останніх комітів зі спільної копії (наприклад, з GitHub). Протилежність push.","also":["пул","пулити","git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Основна гілка","text":"Офіційна версія коду, від якої всі працюють; її часто називають main або master.","also":["main","master","головна гілка","основної гілки","головної гілки","main branch","master branch"]},{"id":"conflict","g":"build","word":"Конфлікт злиття","text":"Коли дві зміни по-різному зачіпають одні й ті самі рядки, комп'ютер не може їх поєднати, і обирати доводиться людині.","also":["конфлікти злиття","конфлікту злиття","мерж-конфлікт","мерж-конфлікти","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (різниця)","text":"Вигляд, який показує, що саме змінилося між двома версіями: які рядки додано, а які прибрано.","also":["діфф","diff","diffs"]},{"id":"fork","g":"build","word":"Форк","text":"Твоя власна копія чужого репозиторію, яку можна змінювати, не зачіпаючи оригінал.","also":["форки","форку","форкнути","fork","forks","forked"]},{"id":"script","g":"build","word":"Скрипт","text":"Коротка програма, яка сама робить одну справу, наприклад наводить лад у файлах чи запускає застосунок.","also":["скрипти","скрипту","скриптів","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Збірка","text":"Перетворення коду на щось готове до запуску, а також сам готовий до запуску результат.","also":["збірки","збірку","білд","білди","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Компіляція","text":"Переклад коду, який написали люди, у вигляд, який комп'ютер може виконувати напряму.","also":["компілювати","компіляції","компілятор","компілятора","compile","compiler"]},{"id":"cli","g":"build","word":"Командний рядок (CLI)","text":"Текстове вікно, у якому ти друкуєш комп'ютеру команди, а не клікаєш мишею. Ще це називають терміналом.","also":["термінал","терміналу","консоль","консолі","командного рядка","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Конфігурація (конфіг)","text":"Налаштування, що керують поведінкою програми; їх зберігають окремо від коду, щоб їх було легко змінювати.","also":["конфіг","конфігу","конфігурації","налаштування","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Змінна середовища","text":"Налаштування, яке передають програмі під час запуску; у ній часто зберігають адреси чи паролі, щоб не писати їх просто в коді.","also":["змінні середовища","змінну середовища","змінних середовища","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Налагодження","text":"Пошук причини, чому щось не працює, і її виправлення.","also":["дебаг","дебагу","налагоджувати","налагодження","debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Парне програмування","text":"Двоє (або людина і ШІ) працюють над одним кодом разом: один друкує, інший перевіряє.","also":["парного програмування","пейринг","pair programming","pairing"]},{"id":"docs","g":"build","word":"Документація","text":"Письмові пояснення того, як щось влаштоване і як цим користуватися.","also":["доки","документи","документації","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README (Рідмі)","text":"Перший файл, який варто прочитати в репозиторії: що це за проєкт і як його запустити.","also":["рідмі","README","READMEs"]},{"id":"legacy","g":"build","word":"Успадкована система (Legacy)","text":"Стара система, яка досі використовується і яку важко змінювати, часто тому, що її розуміє вже мало хто.","also":["леґасі","легасі","успадкований код","успадкованого коду","успадковані системи","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Технічний борг","text":"Скорочення шляху, що зараз заощаджують час, але сповільнюють майбутні зміни, як кредит, на який наростають відсотки. Рефакторинг гасить цей борг.","also":["техборг","техборгу","технічного боргу","technical debt","tech debt"]},{"id":"test","g":"test","word":"Тест","text":"Перевірка, що щось працює як треба. Одні тести комп'ютер запускає сам за кожної зміни коду, інші — це ти, коли пробуєш готову картку, перш ніж прийняти її.","also":["тести","тесту","тестів","тестування","тестувати","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Скорочення від quality assurance, тобто контроль якості: усе, що робиться, щоб робота була правильною до виходу у світ. В AI-gile це автоматичні перевірки: якщо QA червоний, щось не пройшло, і поки це не виправлять, у світ нічого не вийде.","also":["контроль якості","перевірки якості","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"Купка тестів","text":"Готові картки, які чекають, поки ти їх спробуєш, одна за одною. Прийми картку або поверни її з приміткою, і з'явиться наступна.","also":["купки тестів","test pile","test piles"]},{"id":"autotest","g":"test","word":"Автоматичний тест","text":"Перевірка, яку комп'ютер запускає сам за кожної зміни коду, щоб рано виявити помилки.","also":["автотест","автотести","автотестів","автоматичні тести","автоматичних тестів","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ручний тест","text":"Людина сама вручну перевіряє роботу, чи поводиться вона так, як треба.","also":["ручні тести","ручного тесту","ручне тестування","ручного тестування","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Модульний тест (unit-тест)","text":"Маленька автоматична перевірка одного крихітного шматочка коду окремо від решти.","also":["модульні тести","модульного тесту","юніт-тест","юніт-тести","юніт-тестів","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Інтеграційний тест","text":"Перевірка того, що кілька частин правильно працюють разом, а не лише по одній.","also":["інтеграційні тести","інтеграційного тесту","інтеграційних тестів","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Наскрізний тест (E2E)","text":"Тест, який діє як справжній користувач від початку до кінця, наприклад реєструється, купує й платить.","also":["E2E","наскрізні тести","наскрізного тесту","наскрізне тестування","end-to-end tests"]},{"id":"uat","g":"test","word":"Приймальне тестування (UAT)","text":"Ті, хто просив про роботу, самі пробують її і кажуть, чи робить вона те, що їм потрібно. Купка тестів в AI-gile — це його варіант.","also":["UAT","acceptance testing","приймання","приймального тестування","приймальні тести"]},{"id":"regression","g":"test","word":"Регресія","text":"Щось, що раніше працювало, але зламалося після зміни. Регресійні тести перевіряють, що старе досі працює.","also":["регресії","регресію","регресій","регресійний тест","регресійні тести","регресійне тестування","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Димовий тест (smoke test)","text":"Дуже швидка перевірка, що головне взагалі працює, наприклад одразу після виходу зміни. Якщо вона не проходить, зупинись і розберись.","also":["смоук-тест","смоук-тести","димові тести","димове тестування","smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Дослідницьке тестування","text":"Вільно пробувати продукт і тикати в нього по-різному, щоб знайти проблеми, які пропустять заздалегідь заплановані перевірки.","also":["експлораторне тестування","дослідницького тестування","дослідницькі тести","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Тест-кейс","text":"Один записаний сценарій для перевірки: кроки і те, що має вийти.","also":["тест-кейси","тест-кейсу","тест-кейсів","тестовий сценарій","тестові сценарії","test case","test cases"]},{"id":"coverage","g":"test","word":"Покриття тестами","text":"Яка частина коду перевіряється автоматичними тестами. Зазвичай що більше, то надійніше, але високе покриття саме по собі не доводить, що все працює добре.","also":["покриття коду","покриття тестами","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Тестові дані","text":"Вигадана інформація для прикладу, яку використовують під час тестування, щоб не розкривати особисті дані справжніх людей.","also":["тестових даних","фікстури","фікстур","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Крайній випадок","text":"Незвичайна ситуація на межі можливого, наприклад порожня форма чи ім'я з апострофом, де все часто ламається.","also":["крайні випадки","крайнього випадку","граничний випадок","граничні випадки","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Щасливий шлях","text":"Звичайний маршрут, коли все йде як треба. Добре тестування перевіряє й нещасливі шляхи."},{"id":"perftest","g":"test","word":"Тестування продуктивності","text":"Перевірка, наскільки швидко щось працює і як воно справляється з навантаженням.","also":["тест продуктивності","тести продуктивності","тестування продуктивності","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Навантажувальне тестування","text":"Перевірка, як система справляється, коли нею користується одразу багато людей.","also":["навантажувальний тест","навантажувальні тести","навантажувального тестування","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Тестування безпеки","text":"Пошук слабких місць, якими хтось міг би скористатися, щоб зловживати системою або побачити те, чого бачити не повинен.","also":["тест безпеки","тести безпеки","тестування безпеки","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Тестування доступності","text":"Перевірка, що людям з різними можливостями зручно користуватися продуктом, зокрема з програмою зчитування з екрана або лише з клавіатурою.","also":["тест доступності","тести доступності","тестування доступності","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Лінтинг","text":"Автоматична перевірка, що знаходить імовірні помилки й неохайний стиль у коді, як перевірка орфографії для програм.","also":["лінтер","лінтера","лінтинг","лінтингу","linting","linter","lint"]},{"id":"static","g":"test","word":"Статичний аналіз","text":"Автоматична перевірка коду на проблеми: програма читає код, не запускаючи його.","also":["статичний аналіз коду","статичного аналізу","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Нестабільний тест (flaky)","text":"Тест, який то проходить, то падає без видимої причини, тому йому не можна цілком довіряти.","also":["нестабільні тести","нестабільного тесту","флекі-тест","флекі-тести","мерехтливий тест","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Відтворення (repro)","text":"Навмисно змусити баг статися знову, повторивши ті самі кроки, щоб його можна було вивчити й виправити. Записати ці кроки — найкорисніша частина звіту про баг.","also":["репро","кроки відтворення","кроків відтворення","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Серйозність","text":"Наскільки тяжкі наслідки проблеми: від дрібної прикрості до зупинки всього.","also":["критичність","критичності","серйозності","рівень серйозності","severity","severity level"]},{"id":"deploy","g":"change","word":"Деплой","text":"Копіювання нової версії програми на комп'ютери, на яких вона працює, наприклад на тестову копію чи на робочу службу."},{"id":"release","g":"change","word":"Реліз","text":"Набір готової роботи з назвою, який виходить у світ разом, із короткими нотатками про те, що змінилося. 🚀 Релізи пише ці нотатки з готових карток.","also":["релізи","релізу","релізів","release","releases"]},{"id":"rollback","g":"change","word":"Відкат","text":"Повернення до останньої версії, яка працювала, коли нова створює проблеми. В AI-gile «Відкат» збирає кроки скасування, записані в кожній зміні, в один чекліст.","also":["відкату","відкотити","відкочено","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Продакшн","text":"Справжня версія, якою користуються люди, на відміну від копії, щоб щось спробувати. Коли щось туди потрапляє, кажуть, що воно виходить у світ. Розробники називають це продакшн або просто прод.","also":["прод","робоча версія","наживо","live","production"],"noTip":1},{"id":"change","g":"change","word":"Зміна","text":"Запланована зміна в чомусь, на що покладаються люди, спершу записана: що, навіщо, який ризик, коли і як її скасувати. Почни з 🔀 Створити запит на зміну.","also":["зміни","змін","запит на зміну","запити на зміну","change","change request"],"noTip":1},{"id":"risk","g":"change","word":"Ризик","text":"Те, що може піти не так, з оцінкою, наскільки це ймовірно і наскільки погано. ⚠️ Ризики тримає їх в одному списку, найвища оцінка зверху, і в кожного є дата, коли переглянути знову.","also":["ризики","ризиків","реєстр ризиків","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Вікно змін","text":"Час, коли зміни можна випускати у світ, наприклад спокійний вівторковий вечір. Поза вікном картку зміни не можна завершити, хіба що це термінова ситуація.","also":["вікна змін","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Остання перевірка просто перед виходом зміни: кожен, хто має її схвалити, каже Go або No go. Зміна йде далі, лише коли всі сказали Go.","also":["go/no go","go-no-go","так чи ні"]},{"id":"approval","g":"change","word":"Погодження","text":"Очікування «так» перед початком роботи. Картка, яку створив друг, або зміна чекає в ✅ Погодження, доки ти її не погодиш чи не відхилиш.","also":["погодити","схвалення","approval","approvals"]},{"id":"quiettime","g":"change","word":"Тихі години","text":"Проміжок часу, наприклад під час стриму, демо чи вночі, коли нічого не виходить у світ. Команди далі працюють і тестують, але вихід чекає, доки він не скінчиться. Ще це називають заморожуванням змін.","also":["тихий час","заморожування змін","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Спосіб роботи, за якого ті, хто створює програми, і ті, хто їх запускає, працюють як одна команда й багато що автоматизують, щоб зміни виходили часто й безпечно."},{"id":"cicd","g":"change","word":"CI/CD (безперервна інтеграція і постачання)","text":"Зміни всіх часто зливаються в основну версію і щоразу автоматично перевіряються (безперервна інтеграція), тому програму завжди можна випустити натисканням кнопки (безперервне постачання).","also":["CI/CD","CI","CD","безперервна інтеграція","безперервної інтеграції","безперервне постачання","безперервного постачання","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Безперервне розгортання","text":"Крок далі за безперервне постачання: кожна зміна, що пройшла перевірки, сама виходить у роботу, і натискати нічого не треба.","also":["безперервного розгортання","continuous deployment","continuous deployments","автодеплой"]},{"id":"pipeline","g":"change","word":"Конвеєр (пайплайн)","text":"Автоматичний ланцюжок кроків, які проходить зміна на шляху в робочу версію, наприклад збірка, тест, потім розгортання.","also":["пайплайн","пайплайни","пайплайну","конвеєр","конвеєра","pipeline","pipelines"]},{"id":"environment","g":"change","word":"Середовище","text":"Окрема копія системи для однієї мети, наприклад одна для розробки, одна для тестування і робоча.","also":["оточення","середовища","середовищ","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Середовище розробки","text":"Копія, у якій працює розробник, часто на своєму комп'ютері, де зламати щось нікому не зашкодить.","also":["оточення розробки","середовища розробки","dev environment","development environment"]},{"id":"testenv","g":"change","word":"Тестове середовище","text":"Окрема копія системи лише для тестування, щоб не чіпати справжній сервіс.","also":["тестове оточення","тестового середовища","test environment","test environments"]},{"id":"staging","g":"change","word":"Стейджинг","text":"Остання копія, налаштована точно як робоча, для фінальної перевірки перед виходом зміни в роботу.","also":["стейджингу","передпродакшен","staging","staging environment"]},{"id":"artifact","g":"change","word":"Артефакт збірки","text":"Файл або пакет, що виходить у результаті збірки і готовий до зберігання, перевірки чи запуску.","also":["артефакти збірки","артефакту збірки","артефакт","артефакти","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Хотфікс","text":"Термінове виправлення, яке швидко випускають поза звичайним планом, бо зламалося щось важливе.","also":["хотфікси","хотфіксу","термінове виправлення","термінові виправлення","hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Патч","text":"Невелике оновлення, яке виправляє баг або закриває діру в безпеці. Швидко ставити патчі безпеки важливо.","also":["латка","латки","патчі","патча","патчів","patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Номер версії","text":"Мітка на кшталт 2.4.1, яка каже, який у тебе випуск. Часто перша цифра змінюється за великих змін, а остання — за дрібних виправлень.","also":["номери версій","номера версії","семантичне версіонування","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Примітки до випуску","text":"Короткий простий список того, що змінилося у випуску, для тих, хто ним користується: виправлення й відомі обмеження. Ще це називають чейнджлогом.","also":["примітки до випуску","приміток до випуску","список змін","чейнджлог","changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Прапорець функції (feature flag)","text":"Перемикач «увімк./вимк.» для функції: нову роботу можна випустити прихованою і ввімкнути (або знову вимкнути) без нового випуску.","also":["фіча-флаг","фіча-флаги","прапорці функцій","перемикач функції","feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Виправлення вперед (roll forward)","text":"Виправити невдалий випуск, швидко випустивши нову виправлену версію замість повернення до старої.","also":["виправлення вперед","roll forward","rolling forward","rolled forward","відкат уперед"]},{"id":"canary","g":"change","word":"Канарковий випуск","text":"Спершу випустити зміну для невеликої групи, а для всіх — лише коли все виглядає нормально. Назва пішла від канарок, яких шахтарі брали під землю як ранній сигнал небезпеки.","also":["канаркове розгортання","канаркового випуску","канарка","canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Синьо-зелене розгортання","text":"Тримати дві копії робочої системи й перемикати людей на нову одразу всіх, щоб у разі невдачі відразу перемкнутися назад.","also":["синьо-зеленого розгортання","blue-green","blue-green deployment","blue green deployment","blue/green"]},{"id":"zerodown","g":"change","word":"Розгортання без простою","text":"Випуск нової версії так, щоб сервіс жодної хвилини не зупинявся для користувачів.","also":["без простою","розгортання без простою","zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Керування змінами","text":"Допомога в тому, щоб зміни проходили успішно: оцінити ризик, отримати потрібне погодження й обрати вдалий час. Ще це називають управлінням змінами.","also":["управління змінами","керування змінами","change enablement","change management","чейндж-менеджмент"]},{"id":"cab","g":"change","word":"Рада зі змін (CAB)","text":"Група, яка розглядає важливі зміни й вирішує, чи можна їх робити і коли.","also":["CAB","change advisory board","КАБ","ради зі змін"]},{"id":"stdchange","g":"change","word":"Стандартна зміна","text":"Малоризикова зміна, яку щоразу роблять одним і тим самим перевіреним способом, тому її погоджено заздалегідь.","also":["стандартні зміни","стандартної зміни","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Звичайна зміна","text":"Зміна, яку треба перевірити й погодити, перш ніж її впроваджувати.","also":["нормальна зміна","звичайні зміни","звичайної зміни","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Екстрена зміна","text":"Зміна, яку треба зробити негайно, щоб усунути серйозну проблему або запобігти їй; погодження при цьому теж прискорене.","also":["аварійна зміна","екстрені зміни","екстреної зміни","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Автоматизація","text":"Доручити комп'ютеру роботу, що повторюється, щоб вона робилася швидше й щоразу однаково.","also":["автоматизувати","автоматизації","автоматизовано","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Інфраструктура","text":"Машини, мережі й служби, на яких працює програма.","also":["інфра","інфраструктури","infrastructure","infra"]},{"id":"iac","g":"change","word":"Інфраструктура як код (IaC)","text":"Опис серверів і налаштувань у файлах, що зберігаються поруч із кодом, щоб їх можна було щоразу відтворити точно так само.","also":["IaC","infrastructure as code","інфраструктури як коду"]},{"id":"cloud","g":"change","word":"Хмара","text":"Оренда комп'ютерів, сховища й послуг у великого постачальника через інтернет замість власних машин.","also":["хмари","хмарі","у хмарі","хмарні обчислення","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Хмарний провайдер","text":"Компанія, що здає в оренду обчислення через інтернет, наприклад Amazon Web Services (AWS), Microsoft Azure чи Google Cloud.","also":["хмарні провайдери","хмарного провайдера","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Хостинг","text":"Місце, де живе й працює твій застосунок чи сайт, щоб люди могли до нього дістатися; зазвичай його орендують у компанії.","also":["хостити","хостингу","hosting"]},{"id":"domain","g":"change","word":"Доменне ім'я","text":"Вебадреса, яку люди вводять, наприклад example.com. Її орендують на рік, тому її треба продовжувати.","also":["домен","домени","домену","доменів","доменного імені","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Скорочення від «система доменних імен»: адресна книга інтернету, яка перетворює ім'я на кшталт example.com на адресу потрібного комп'ютера.","also":["ДНС","система доменних імен","системи доменних імен","domain name system"]},{"id":"container","g":"change","word":"Контейнер","text":"Запечатаний пакет із застосунком і всім, що йому потрібне, щоб він працював однаково на будь-якому комп'ютері. Найвідоміший інструмент — Docker.","also":["контейнери","контейнера","контейнерів","Docker","докер","container","containers"],"noTip":1},{"id":"vm","g":"change","word":"Віртуальна машина (ВМ)","text":"Несправжній комп'ютер, що працює всередині справжнього, щоб одна велика машина могла працювати як багато.","also":["ВМ","віртуальні машини","віртуальної машини","віртуалка","VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Безсерверні обчислення (Serverless)","text":"Запуск коду без потреби власноруч займатися серверами: провайдер запускає його, коли потрібно, а ти платиш лише за використане."},{"id":"lb","g":"change","word":"Балансувальник навантаження","text":"Програма чи пристрій, що розподіляє відвідувачів між кількома серверами, щоб жоден не перевантажувався.","also":["балансувальник","балансувальника","балансувальники","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Кеш","text":"Зручне сховище недавніх результатів під рукою, щоб одне й те саме не доводилося завантажувати чи рахувати знову. Очищення кешу може допомогти, якщо сторінки виглядають застарілими.","also":["кешу","кешування","кешувати","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Мережа доставки контенту (CDN)","text":"Всесвітній набір серверів із копіями твоїх сторінок і картинок поруч із відвідувачами, щоб усе швидко завантажувалося.","also":["CDN","ЦДН","мережі доставки контенту"]},{"id":"migration","g":"change","word":"Міграція","text":"Перенесення даних чи систем зі старого місця на нове або обережна зміна будови бази даних.","also":["міграції","міграцію","міграцій","міграція бази даних","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Сервіс","text":"Щось, що ти створив і на що покладаються люди, як-от сайт чи застосунок, і за чим доглядають, щоб воно працювало. Постав позначку «Цей проєкт — сервіс» і вкажи, що він пропонує, хто ним користується і хто чергує.","also":["сервіси","сервісу","сервісів","service","services"]},{"id":"uptimepct","g":"run","word":"Час безвідмовної роботи (uptime)","text":"Яку частину часу послуга працює, зазвичай у відсотках. За 99,9% усе одно набігає близько 43 хвилин простою на місяць.","also":["аптайм","аптайму","часу безвідмовної роботи","uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Перевірка доступності","text":"Автоматична перевірка кожні кілька хвилин, що твій сервіс досі відповідає. Якщо вона не проходить кілька разів поспіль, AI-gile сам відкриває картку інциденту.","also":["перевірки доступності","перевірка доступності","uptime checks","uptime check"]},{"id":"statuspage","g":"run","word":"Сторінка статусу","text":"Публічна сторінка, яка показує, чи працює сервіс (зелений, помаранчевий чи червоний), з останнім оновленням, щоб люди, які ним користуються, могли перевірити самі, а не питати.","also":["сторінки статусу","статус-сторінка","status page","status pages"]},{"id":"desk","g":"run","word":"Служба підтримки","text":"Місце, куди надходять питання і повідомлення від людей, які користуються твоїм сервісом. AI-gile відносить кожне до запиту, інциденту чи ідеї і каже, якщо воно схоже на щось, про що вже повідомляли.","also":["служби підтримки","підтримка","сервіс-деск","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Запит на обслуговування","text":"Хтось просить про звичайну річ, наприклад новий обліковий запис чи трохи допомоги, а не повідомляє, що щось зламалося. Запит чекає своєї черги; інцидент іде першим.","also":["запити на обслуговування","запит","service request","service requests"]},{"id":"incident","g":"run","word":"Інцидент","text":"Щось, що зламалося або працює неправильно для людей, які цим користуються просто зараз, наприклад сайт не працює чи дуже гальмує. Картка 🔥 інциденту йде поза чергою: спершу треба знову все запустити.","also":["інциденти","інциденту","інцидентів","incident","incidents"]},{"id":"major","g":"run","word":"Великий інцидент","text":"Великий інцидент: зачеплено багато людей або під загрозою гроші чи дані. Одна кнопка кидає на нього всі команди (рій), будить того, хто чергує, і просить оновлення статусу кожні 30 хвилин.","also":["великі інциденти","серйозний інцидент","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Чергування","text":"Бути тим, хто відповідає, коли щось ламається, навіть уночі. У кожного сервісу є черговий учасник команди, якого будять першим через його інциденти.","also":["черговий","чергова зміна","на чергуванні","on call","on-call"]},{"id":"replyby","g":"run","word":"Час відповіді","text":"Скільки картка може чекати на першу відповідь, наприклад годину для інциденту. Після цього на ній з'являється червоний годинник, щоб ніщо тихо не забулося. Ще це називають цільовим часом відповіді.","also":["термін відповіді","цільовий час відповіді","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Розбір інциденту","text":"Короткий погляд назад після інциденту: що сталося, що допомогло і що змінити, без пошуку винних. Без нього інцидент не можна закрити. Ще кажуть «постмортем».","also":["розбори інцидентів","постмортем","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Проблема","text":"Прихована причина одного чи кількох інцидентів. Картка 🧩 проблеми збирає інциденти, які повертаються знову і знову, щоб причину знайшли і виправили назавжди.","also":["проблеми","проблем","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Першопричина","text":"Справжня причина, чому щось зламалося, а не лише те, що ти бачив. Виправ першопричину, і інцидент перестане повертатися.","also":["першопричини","коренева причина","root cause","root causes"]},{"id":"workaround","g":"run","word":"Обхідний шлях","text":"Спосіб, щоб усе працювало, поки справжнє виправлення не готове, наприклад перезапустити щось, коли воно зависає. Його записують у картці проблеми, щоб нікому не довелося вигадувати його знову.","also":["обхідні шляхи","тимчасове рішення","воркераунд","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Відома помилка","text":"Проблема, причину якої зрозуміли, але яку ще не виправили, зазвичай із записаним обхідним шляхом. Розділ 🧩 «Відомі помилки» збирає їх, щоб усі користувалися обхідним шляхом і не копали заново.","also":["відомі помилки","відомих помилок","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Покрокова інструкція, як виправити відомий вид проблеми, щоб це робили однаково і швидко щоразу. Після великого інциденту команда може запропонувати runbook, а ти його схвалиш.","also":["runbooks","ранбук","інструкція","покрокова інструкція"]},{"id":"ci","g":"run","word":"Елемент конфігурації","text":"Одна річ, від якої залежить твій сервіс: сервер, домен, сертифікат, ключ або постачальник. 🗂️ Елементи показує їх для кожного сервісу, тож видно, чого торкається інцидент і що треба поновити або зарезервувати.","also":["елементи конфігурації","елементів конфігурації","елементи","configuration item","configuration items"]},{"id":"expiry","g":"run","word":"Термін дії","text":"Дата, після якої щось перестає працювати, якщо його не продовжити, наприклад сертифікат безпеки сайту чи його вебадреса. AI-gile стежить за цими датами і за 30 днів створює по одній картці на продовження, щоб нічого не зупинилося несподівано.","also":["терміни дії","закінчення терміну","стеження за термінами","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"Резервна копія","text":"Збережена раніше копія твоїх даних, на яку можна спертися, якщо щось загубилося чи пошкодилося. AI-gile щодня робить резервну копію твоїх дошок.","also":["резервні копії","бекап","бекапи","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Відновлення","text":"Повернення даних із резервної копії. Резервна копія насправді чогось варта, лише коли ти знаєш, що її можна відновити, тож варто час від часу пробувати.","also":["відновити","відновлено","restore","restored"]},{"id":"svcreview","g":"run","word":"Огляд сервісу","text":"Погляд назад на один місяць сервісу: відкриті й виправлені інциденти, як швидко люди отримували відповідь, доступність і використані токени. Місячний огляд показує це для кожного сервісу.","also":["огляди сервісу","місячний огляд","місячні огляди","service review","monthly review"]},{"id":"accessreview","g":"run","word":"Перевірка доступу","text":"Кожні 90 днів перевіряємо, хто ще може зайти: посилання для спільного доступу, ролі друзів, збережені паролі й ключі. Ти залишаєш або прибираєш кожен, щоб старий доступ не залежувався.","also":["перевірки доступу","access review","access reviews"]},{"id":"improvements","g":"run","word":"Список покращень","text":"Усе, що команда вирішила робити краще, в одному місці: пропозиції з ретро, дії з розборів і виправлення проблем, кожне зі своїм статусом. Шукай у 📈 Покращення.","also":["списки покращень","покращення","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Ліміт токенів","text":"Місячний ліміт токенів, які можуть використати агенти сервісу. На 80% ти отримуєш попередження; на 100% їхня фонова робота чекає до наступного місяця або доки ти не піднімеш ліміт.","also":["ліміти токенів","місячний ліміт токенів","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Керування послугами","text":"Усе, що потрібно, щоб послуга залишалася корисною й працювала для тих, хто на неї покладається, день за днем.","also":["керування сервісом","керування послугами","керування послугою","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Широко вживаний посібник із хорошого керування послугами: інциденти, проблеми, зміни та багато іншого. Назва колись розшифровувалася як IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Керування ІТ-послугами (ITSM)","text":"Робота з технологіями як з послугою для людей, із зрозумілими способами обробляти запити, інциденти, зміни й покращення.","also":["ITSM","IT service management","керування ІТ-послугами"]},{"id":"managed","g":"run","word":"Керована послуга","text":"Послуга, яку для тебе запускає й обслуговує хтось інший за домовленістю про те, наскільки добре вона має працювати.","also":["керована послуга","керовані послуги","керованої послуги","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Власник послуги","text":"Людина, яка відповідає за послугу загалом: наскільки добре вона працює, скільки коштує і як покращується.","also":["власники послуг","власника послуги","власник сервісу","service owner","service owners"]},{"id":"sla","g":"run","word":"Угода про рівень послуг (SLA)","text":"Письмова обіцянка клієнтам, наскільки добре працюватиме послуга, наприклад «доступна 99,9% часу» чи «відповідь протягом години», часто з поверненням грошей, якщо обіцянку порушено.","also":["SLA","SLAs","СЛА","угода про рівень послуг","угоди про рівень послуг","service level agreement"]},{"id":"slo","g":"run","word":"Ціль за рівнем послуг (SLO)","text":"Власна ціль команди щодо того, наскільки добре послуга має працювати за період; її зазвичай ставлять трохи суворіше, ніж у SLA, про запас.","also":["SLO","SLOs","СЛО","цілі за рівнем послуг"]},{"id":"sli","g":"run","word":"Показник рівня послуг (SLI)","text":"Справжнє вимірювання, яке звіряють із ціллю, наприклад частка відвідувань, за яких усе завантажилося нормально.","also":["SLI","SLIs","СЛІ","показники рівня послуг"]},{"id":"availability","g":"run","word":"Доступність (availability)","text":"Чи можуть люди користуватися послугою, коли вона їм потрібна; часто вимірюється часом безвідмовної роботи.","also":["висока доступність","високої доступності","availability","high availability"]},{"id":"downtime","g":"run","word":"Простій (downtime)","text":"Час, коли послуга не працює або вимкнена, запланований чи ні.","also":["даунтайм","простою","простої","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Бюджет помилок","text":"Невеликий обсяг збоїв, який допускає твоя ціль щодо надійності. Поки він не вичерпаний, можна ризикувати зі змінами; коли закінчився — треба пригальмувати.","also":["бюджету помилок","бюджети помилок","error budget","error budgets"]},{"id":"outage","g":"run","word":"Аварія","text":"Час, коли послуга не працює або сильно зламана для користувачів.","also":["аварії","аварію","outage","outages"]},{"id":"degraded","g":"run","word":"Деградація послуги","text":"Працює, але погано: повільно або з частиною функцій, що не працюють.","also":["деградація","деградації","працює з погіршенням","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Моніторинг","text":"Постійне автоматичне спостереження за послугою, щоб проблеми помічали, в ідеалі раніше за користувачів.","also":["моніторингу","monitoring"]},{"id":"observability","g":"run","word":"Спостережуваність","text":"Наскільки добре за журналами, числами й трасуваннями можна зрозуміти ззовні, що відбувається всередині системи.","also":["спостережуваності","observability","o11y"]},{"id":"log","g":"run","word":"Журнал (лог)","text":"Щоденник, який веде програма про те, що вона робить; за ним з'ясовують, що пішло не так.","also":["лог","логи","логів","журнали","журналу","журналів","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Трасування","text":"Запис того, як один запит крок за кроком проходить крізь різні частини системи; видно, де він сповільнився.","also":["трейс","трейси","трасування","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Затримка (latency)","text":"Скільки часу йде на відповідь, наприклад очікування між натисканням і появою сторінки.","also":["латентність","latency"]},{"id":"alert","g":"run","word":"Сповіщення (алерт)","text":"Автоматичне повідомлення про те, що щось потребує уваги, наприклад сайт не відповідає.","also":["алерт","алерти","алертів","сповіщення","сповіщень","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Втома від сповіщень","text":"Коли сповіщень так багато, що люди перестають на них зважати, зокрема й на важливі.","also":["втоми від сповіщень","втома від алертів","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Дашборд","text":"Екран, на якому найважливіші числа й стани видно одним поглядом.","also":["дашборди","дашборду","панель моніторингу","панель керування","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Виклик чергового (paging)","text":"Терміново викликати чергового, навіть розбудити, через проблему.","also":["пейджинг","виклику чергового","paging","paged"]},{"id":"escalation","g":"run","word":"Ескалація","text":"Залучення того, хто має більше вмінь чи повноважень, коли питання не можна розв'язати на поточному рівні або недостатньо швидко.","also":["ескалювати","ескалації","ескалацію","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Сортування (тріаж)","text":"Швидке розбирання вхідних питань за терміновістю й важливістю, щоб найгіршим зайнялися першим.","also":["тріаж","тріажу","triage","triaged"]},{"id":"impact","g":"run","word":"Вплив (impact)","text":"Наскільки щось зачіпає людей: скільки їх і наскільки сильно.","noTip":1},{"id":"urgency","g":"run","word":"Терміновість","text":"Як швидко потрібно зайнятися питанням. Вплив і терміновість разом визначають пріоритет.","noTip":1},{"id":"plevels","g":"run","word":"Рівні пріоритету (P1, P2…)","text":"Мітки, що показують, наскільки термінове питання. P1 — найсерйозніше, діяти треба негайно.","also":["P1","P2","P3","P4","рівні пріоритету","рівня пріоритету","priority levels"]},{"id":"queue","g":"run","word":"Черга тікетів","text":"Список запитів та інцидентів, які чекають, поки їх візьмуть у роботу.","also":["черги тікетів","черзі тікетів","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Перша і друга лінія","text":"Рівні підтримки: перша лінія приймає дзвінок і розв'язує просте, у другої лінії глибші знання для складного. Їх ще називають tier 1 і tier 2.","also":["перша лінія","друга лінія","першої лінії","другої лінії","підтримка першої лінії","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Керівник інциденту","text":"Одна людина, яка керує реакцією на інцидент, щоб усі знали, хто вирішує і хто що робить.","also":["керівника інциденту","командир інциденту","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Час реакції","text":"Скільки минає часу, перш ніж хтось уперше візьме запит чи інцидент у роботу.","also":["часу реакції","час відгуку","response time","response times"]},{"id":"resolution","g":"run","word":"Час вирішення","text":"Скільки часу йде на те, щоб повністю розібратися із запитом чи інцидентом: від повідомлення до виправлення.","also":["часу вирішення","час усунення","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Середній час відновлення (MTTR)","text":"Скільки в середньому йде часу, щоб знову запустити послугу після поломки. MTTR можуть розуміти трохи по-різному, тому кажи, що саме ти вимірюєш.","also":["MTTR","середнього часу відновлення","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Середній час між відмовами (MTBF)","text":"Скільки в середньому послуга працює, перш ніж щось зламається.","also":["MTBF","середнього часу між відмовами","mean time between failures"]},{"id":"cmdb","g":"run","word":"База даних конфігурацій (CMDB)","text":"Список усіх елементів конфігурації та того, як вони пов'язані, щоб бачити, що від чого залежить.","also":["CMDB","бази даних конфігурацій","configuration management database"]},{"id":"asset","g":"run","word":"Актив","text":"Усе цінне, чим ти володієш або за що платиш, щоб послуга працювала: ноутбук, ліцензія на програму чи домен.","also":["активи","активу","активів","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Планування потужностей","text":"Турбота про те, щоб обчислювальної потужності, місця для зберігання й людей вистачило на те, що попереду.","also":["планування потужностей","план потужностей","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Масштабування","text":"Справлятися зі зростанням кількості користувачів, додаючи машині потужності (вертикальне масштабування) або додаючи більше машин (горизонтальне).","also":["масштабувати","масштабування","вертикальне масштабування","горизонтальне масштабування","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Безперервність бізнесу","text":"Плани на те, щоб важливе продовжувало працювати, коли стається щось серйозне, наприклад втрата офісу, ключового постачальника чи комп'ютерів.","also":["безперервності бізнесу","план безперервності бізнесу","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Аварійне відновлення (DR)","text":"План і засоби, щоб повернути послугу в стрій після чогось серйозного, наприклад втрати цілого центру обробки даних.","also":["DR","аварійного відновлення","відновлення після збою","відновлення після аварії","disaster recovery"]},{"id":"rto","g":"run","word":"Цільовий час відновлення (RTO)","text":"Найдовший час, який послуга може простоювати після катастрофи, перш ніж вона має знову запрацювати.","also":["RTO","цільового часу відновлення","recovery time objective"]},{"id":"rpo","g":"run","word":"Цільова точка відновлення (RPO)","text":"Скільки нещодавніх даних можна дозволити собі втратити, у вимірі часу. RPO в одну годину означає резервні копії щонайменше щогодини.","also":["RPO","цільової точки відновлення","recovery point objective"]},{"id":"redundancy","g":"run","word":"Резервування","text":"Запас напоготові, наприклад другий сервер, щоб одна відмова не зупинила послугу.","also":["резервування","резервуванні","надлишковість","надлишковості","redundancy"]},{"id":"failover","g":"run","word":"Автоперемикання (failover)","text":"Автоматичне перемикання на запасну систему, коли звичайна відмовила.","also":["фейловер","автоперемикання","перемикання на резерв","failover","fail over"]},{"id":"spof","g":"run","word":"Єдина точка відмови","text":"Одна частина, поломка якої тягне за собою все, бо запасної немає.","also":["SPOF","єдиної точки відмови","єдині точки відмови","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Вікно обслуговування","text":"Запланований час, коли послугу можуть призупинити або сповільнити заради обслуговування; користувачів попереджають заздалегідь.","also":["вікна обслуговування","вікно техобслуговування","планові роботи","планових робіт","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Передача справ","text":"Передача роботи, знань і відповідальності іншій людині чи команді, щоб нічого не загубилося.","also":["хендовер","передачі справ","передати справи","handover","handovers"]},{"id":"kb","g":"run","word":"База знань","text":"Збірка довідкових статей і відповідей для користувачів та для команди.","also":["бази знань","базі знань","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Задоволеність клієнтів (CSAT)","text":"Оцінка від користувачів, наскільки вони лишилися задоволені; її часто питають після закриття запиту.","also":["CSAT","задоволеності клієнтів","customer satisfaction"]},{"id":"supplier","g":"run","word":"Постачальник","text":"Стороння компанія, на яку ти покладаєшся, наприклад твій хостинг-провайдер. Її ще називають вендором або третьою стороною.","also":["постачальники","постачальника","постачальників","вендор","вендори","вендора","третя сторона","третьої сторони","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Виведення послуги з експлуатації","text":"Назавжди й безпечно вимкнути послугу: попередити її користувачів, розібратися з її даними й доступом і припинити витрати на неї.","also":["виведення з експлуатації","закриття послуги","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Кінець життєвого циклу (EOL)","text":"Коли виробник припиняє випускати для продукту оновлення й підтримувати його, і його час замінити.","also":["EOL","кінець життєвого циклу","кінця життєвого циклу","кінець підтримки","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Кібербезпека","text":"Захист систем і даних від злому, крадіжки та пошкодження.","also":["кібербезпеки","інформаційна безпека","інформаційної безпеки","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Автентифікація","text":"Перевірка того, хто перед тобою, зазвичай за паролем чи кодом. Часто скорочується до authn.","also":["автентифікації","аутентифікація","аутентифікації","authn","authentication"]},{"id":"authz","g":"sec","word":"Авторизація","text":"Перевірка того, що людині дозволено робити, коли вже відомо, хто вона. Часто скорочується до authz.","also":["авторизації","authz","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Багатофакторна автентифікація (MFA)","text":"Вхід із двома чи більше підтвердженнями, наприклад пароль і код на телефоні. Ще це називають двофакторною автентифікацією (2FA).","also":["MFA","2FA","двофакторна автентифікація","двофакторної автентифікації","багатофакторної автентифікації","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Єдиний вхід (SSO)","text":"Увійти один раз і потрапити в багато систем, наприклад використовувати робочий обліковий запис усюди.","also":["SSO","єдиного входу","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Менеджер паролів","text":"Застосунок, який вигадує надійні паролі й запам'ятовує їх за тебе.","also":["менеджери паролів","менеджера паролів","password manager","password managers"]},{"id":"secret","g":"sec","word":"Секрет","text":"Пароль, ключ чи інший закритий код, з яким програма заходить кудись. Його не можна нікому передавати й не можна записувати в код.","also":["секрети","секрету","секретів","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API-ключ","text":"Секретний код, що дозволяє програмі користуватися API іншої служби й показує, хто користується (і платить).","also":["ключ API","ключі API","API-ключі","API-ключа","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Токен доступу","text":"Тимчасова перепустка, що підтверджує, що програмі можна ввійти, тож пароль щоразу не потрібен. Це не те саме, що токен у ШІ.","also":["токени доступу","токена доступу","токенів доступу","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Шифрування","text":"Перетворення інформації на нечитабельну, щоб прочитати її міг лише той, у кого є потрібний ключ.","also":["шифрування","зашифровано","шифрувати","зашифрувати","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Безпечний спосіб, яким вебсторінки доходять до тебе; його показує замочок у браузері. Дорогою ніхто не може їх прочитати чи змінити."},{"id":"cert","g":"sec","word":"SSL/TLS-сертифікат","text":"Цифрове посвідчення, за допомогою якого сайт доводить, хто він, і може працювати за HTTPS. Його строк дії спливає, тому його треба продовжувати.","also":["TLS-сертифікат","SSL-сертифікат","сертифікат","сертифікати","сертифіката","сертифікатів","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Права доступу","text":"Правила про те, хто що може бачити чи змінювати.","also":["права","прав доступу","дозволи","дозволів","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Принцип найменших привілеїв","text":"Давати кожній людині чи програмі лише той доступ, який їм справді потрібен, і лише на той час, поки він потрібен.","also":["найменших привілеїв","мінімум прав","мінімальні права","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Рольове керування доступом (RBAC)","text":"Видавати доступ за ролями, наприклад «спостерігач» чи «редактор», а не по окремих людях.","also":["RBAC","рольовий доступ","рольового доступу","role-based access"]},{"id":"vuln","g":"sec","word":"Вразливість","text":"Слабке місце, яким хтось може скористатися, щоб зламати систему чи завдати шкоди.","also":["вразливості","вразливостей","уразливість","уразливості","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (вразливість нульового дня)","text":"Слабке місце, про яке зловмисники знають раніше, ніж у творців був час його виправити.","also":["нульовий день","нульового дня","вразливість нульового дня","зеродей","zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Шкідливе ПЗ","text":"Шкідливі програми, наприклад віруси, створені, щоб псувати, шпигувати чи красти.","also":["шкідливе ПЗ","шкідливого ПЗ","шкідливі програми","малвар","malware"]},{"id":"ransomware","g":"sec","word":"Шифрувальник (ransomware)","text":"Шкідлива програма, яка блокує твої файли й вимагає гроші за розблокування. Найкращий захист — добрі резервні копії.","also":["шифрувальник","шифрувальника","програма-вимагач","програми-вимагачі","вимагач","ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"Фішинг","text":"Підроблені повідомлення, що намагаються обманом виманити паролі чи гроші або змусити відкрити щось небезпечне.","also":["фішингу","фішинговий лист","фішингові листи","фішингових листів","phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Соціальна інженерія","text":"Обман людей, а не комп'ютерів, щоб отримати доступ, наприклад фальшивий дзвінок «з техпідтримки»."},{"id":"firewall","g":"sec","word":"Брандмауер (файрвол)","text":"Вартовий, який вирішує, який мережевий трафік можна впускати й випускати.","also":["брандмауер","брандмауера","файрвол","файрвола","міжмережевий екран","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Скорочення від «віртуальна приватна мережа»: закрите, зашифроване з'єднання через інтернет, яке часто використовують, щоб безпечно потрапити в робочі системи.","also":["ВПН","віртуальна приватна мережа","віртуальної приватної мережі","virtual private network"]},{"id":"ddos","g":"sec","word":"Відмова в обслуговуванні (DoS, DDoS)","text":"Заливання послуги такою кількістю несправжнього трафіку, що справжні люди не можуть нею користуватися. DDoS означає, що трафік іде одразу з багатьох комп'ютерів.","also":["DoS","DDoS","ДДоС","DDoS-атака","DDoS-атаки","відмова в обслуговуванні","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Тест на проникнення (пентест)","text":"Дружні експерти, яких наймають, щоб вони спробували зламати систему: слабкі місця знаходять раніше, ніж справжні зловмисники.","also":["пентест","пентести","пентесту","тест на проникнення","тестування на проникнення","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Аудит безпеки","text":"Ретельна перевірка того, наскільки добре щось захищене, за списком надійних практик.","also":["аудит","аудиту","аудити безпеки","аудиту безпеки","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Моделювання загроз","text":"Продумування того, хто може напасти на систему, як і що ти зробиш, щоб їх зупинити.","also":["модель загроз","моделі загроз","моделювання загроз","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Витік даних","text":"Коли особиста інформація потрапляє до тих, у кого її бути не повинно, або губиться чи змінюється без дозволу.","also":["витоки даних","витоку даних","злам даних","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Персональні дані","text":"Будь-які відомості про людину, яку можна впізнати, наприклад ім'я, адреса електронної пошти чи місцеперебування. Ще це називають PII.","also":["PII","персональних даних","особисті дані","особистих даних","personal data","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Європейський закон про персональні дані (у Великій Британії своя версія): збирай лише те, що потрібно, зберігай у безпеці й дозволяй людям дивитися свої дані та видаляти їх.","also":["ЗЗСД","General Data Protection Regulation","Загальний регламент про захист даних","регламент GDPR"]},{"id":"dataprot","g":"sec","word":"Захист даних","text":"Дбайливе поводження з персональними даними в межах закону.","also":["захисту даних","закон про захист даних","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Політика конфіденційності","text":"Відкрита сторінка про те, які персональні дані ти збираєш, навіщо і що з ними робиш.","also":["політика приватності","політики конфіденційності","політики приватності","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Згода","text":"Чітке й добровільне «так» людини на те, щоб її дані використовували певним способом. Її можна забрати назад будь-коли.","also":["згоди","згоду","opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (куки)","text":"Маленький файл, який сайт зберігає у твоєму браузері, щоб дещо пам'ятати, наприклад що ти в системі. Для деяких спершу потрібна твоя згода.","also":["куки","кукі","файли cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Мінімізація даних","text":"Збирати й зберігати лише ті персональні дані, які справді потрібні для справи.","also":["мінімізації даних","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Строк зберігання даних","text":"Як довго дані зберігаються, перш ніж їх видалять. Зберігати їх не довше за необхідне безпечніше, і часто цього вимагає закон.","also":["зберігання даних","строку зберігання","строк зберігання","data retention","retention period"]},{"id":"anon","g":"sec","word":"Анонімізація","text":"Зміна даних так, щоб за ними більше не можна було розумно визначити, про кого йдеться.","also":["анонімізації","анонімізовані дані","анонімні дані","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Псевдонімізація","text":"Заміна імен та інших відомостей кодами; ключ, за яким їх можна зіставити, зберігається окремо. Це все одно персональні дані.","also":["псевдонімізації","псевдонімізовані дані","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Угода про обробку даних (DPA)","text":"Договір про те, як постачальник може поводитися з персональними даними від твого імені.","also":["DPA","угоди про обробку даних","data processing agreement"]},{"id":"dpia","g":"sec","word":"Оцінка впливу на захист даних (DPIA)","text":"Ретельний погляд до початку роботи на те, як план використання персональних даних може вплинути на людей і як знизити ризики.","also":["DPIA","оцінки впливу на захист даних","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Журнал аудиту","text":"Запис про те, хто що зробив і коли, щоб дії можна було перевірити пізніше.","also":["журнали аудиту","журналу аудиту","аудит-лог","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Відповідність вимогам (комплаєнс)","text":"Дотримання законів, правил і стандартів, які до тебе стосуються, і вміння це показати.","also":["комплаєнс","комплаєнсу","відповідності вимогам","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Відомий міжнародний стандарт керування інформаційною безпекою. Компанії можуть проходити за ним сертифікацію.","also":["ISO/IEC 27001","ІСО 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Американський звіт, перевірений зовнішніми аудиторами, який показує, що компанія належним чином дбає про дані клієнтів.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Агент","text":"ШІ, що сам працює над завданням: читає код, вносить зміни, запускає перевірки й звітує. Його роботу все одно перевіряють.","also":["агенти","агентів","agent","agents"]},{"id":"token","g":"ai","word":"Токен","text":"Маленькі шматочки тексту, які ШІ читає й пише, приблизно три чверті слова кожен. Використання ШІ рахують у токенах, тож що їх менше, то більше лишається від твого тарифу.","also":["токени","токенів","token","tokens"]},{"id":"hook","g":"ai","word":"Хук","text":"Маленька команда, яка сама запускається в певний момент, наприклад коли починається ШІ-сесія, щоб команда чула твої коментарі.","also":["хуки","hook","hooks"]},{"id":"ai","g":"ai","word":"Штучний інтелект (ШІ)","text":"Комп'ютерні системи, що роблять те, що ми зазвичай вважаємо справою людини: пишуть, відповідають на запитання, впізнають картинки.","also":["ШІ","AI","штучного інтелекту","artificial intelligence","нейромережа","нейромережі"],"noTip":1},{"id":"ml","g":"ai","word":"Машинне навчання (ML)","text":"Спосіб навчити комп'ютери знаходити закономірності за безліччю прикладів, а не давати їм точні правила.","also":["ML","МН","машинного навчання","machine learning"]},{"id":"model","g":"ai","word":"Модель","text":"Навчений «мозок» ШІ-системи, створений на величезній кількості прикладів. Моделі різняться вміннями, швидкістю й ціною.","also":["моделі","модель ШІ","моделей","ШІ-модель","ШІ-моделі","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Велика мовна модель (LLM)","text":"ШІ-модель, навчена на величезній кількості текстів, тому вона вміє читати й писати мовою людей.","also":["LLM","LLMs","ВММ","мовна модель","мовні моделі","великої мовної моделі","великі мовні моделі"]},{"id":"genai","g":"ai","word":"Генеративний ШІ","text":"ШІ, що створює нове, наприклад текст, картинки чи код, а не лише сортує або розпізнає.","also":["GenAI","генеративного ШІ","генеративний штучний інтелект","Generative AI"]},{"id":"chatbot","g":"ai","word":"Чат-бот","text":"Програма, з якою розмовляють звичайною мовою, текстом або голосом.","also":["чат-боти","чат-бота","чат-ботів","чатбот","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Промпт","text":"Те, що ти даєш ШІ: твоє запитання чи вказівки та все, що ти йому передаєш. Чим зрозуміліший промпт, тим зазвичай краща відповідь.","also":["запит до ШІ","промпти","промпту","промптів","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Промпт-інжиніринг","text":"Вміння писати промпти, що дають надійний і корисний результат.","also":["складання промптів","промпт-інжинірингу","prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Системний промпт","text":"Фонові вказівки, які ШІ отримує до початку розмови: вони задають його роль і правила. Вони важать більше, ніж те, що ти друкуєш.","also":["системні промпти","системного промпту","системна інструкція","системні інструкції","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Контекст","text":"Усе, що ШІ бачить, поки працює: вказівки, твої повідомлення, прочитані файли й попередні відповіді.","noTip":1},{"id":"ctxwin","g":"ai","word":"Контекстне вікно","text":"Скільки ШІ може тримати в голові одночасно, вимірюється в токенах. Усе, що за цією межею, відкидається або стискається.","also":["контекстні вікна","контекстного вікна","вікно контексту","context window","context windows"]},{"id":"session","g":"ai","word":"Сесія","text":"Одна робоча розмова зі ШІ від початку до кінця. Нова сесія починається зі свіжою пам'яттю.","also":["сесії","сесію","сесій","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Пам'ять","text":"Нотатки, які ШІ зберігає між сесіями, щоб пам'ятати твої вподобання й попередні рішення.","noTip":1},{"id":"hallucination","g":"ai","word":"Галюцинація","text":"Коли ШІ каже щось упевнено, але насправді вигадане або неправильне. Важливі факти перевіряй.","also":["галюцинації","галюцинацію","галюцинацій","галюцинувати","галюцинує","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Навчання","text":"Навчання моделі на величезній кількості прикладів до того, як нею почнуть користуватися.","also":["навчання моделі","навчати","навчений","тренування","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Навчальні дані","text":"Приклади, на яких модель училася. Її знання закінчуються на даті, коли ці дані було зібрано.","also":["навчальних даних","навчальна вибірка","навчальної вибірки","training data","training set"]},{"id":"cutoff","g":"ai","word":"Дата відсікання знань","text":"Дата, на якій закінчуються вбудовані знання ШІ. Про пізніші події він не знає, доки не знайде їх сам.","also":["відсікання знань","дати відсікання знань","межа знань","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Дотренування (fine-tuning)","text":"Додаткове навчання готової моделі на твоїх прикладах, щоб вона краще справлялася з однією конкретною справою.","also":["дотренування","файнтюнінг","файнтюнінгу","дотренувати","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Інференс","text":"Коли ШІ-модель справді використовують, щоб відповісти на щось, на відміну від її навчання.","also":["інференсу","виведення моделі","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Використання інструментів","text":"Коли ШІ може не лише говорити, а й робити: запускати команди, читати файли чи шукати в інтернеті через інструменти, які йому дає застосунок.","also":["використання інструментів","виклик інструментів","виклики інструментів","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Субагент","text":"ШІ-помічник, якому головний ШІ доручає невелику роботу і отримує від нього результат.","also":["субагенти","субагента","субагентів","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Мультиагентна система","text":"Кілька ШІ працюють разом над однією справою, у кожного своя частина, як у маленькій команді.","also":["мультиагент","мультиагентні системи","мультиагентної системи","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Автономність","text":"Скільки ШІ може робити сам, перш ніж йому доведеться спитати людину.","also":["автономності","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Людина в контурі","text":"Участь людини, яка перевіряє або схвалює дії ШІ в ключових місцях. В AI-gile це ти.","also":["людина в контурі","людини в контурі","людина в циклі","human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Обмежувачі (guardrails)","text":"Межі й перевірки, що не дають діям ШІ стати небезпечними, наприклад схвалення перед випуском чого-небудь. Вони знижують ризик помилок, але не виключають їх.","also":["обмежувачі","обмежувачів","захисні огорожі","guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Генерація з доповненням пошуком (RAG)","text":"Дозволити ШІ заглянути у твої документи, перш ніж він відповість, щоб його відповіді спиралися на твої факти.","also":["RAG","генерації з доповненням пошуком","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Ембединг","text":"Перетворення тексту на список чисел, що передає його зміст, щоб комп'ютер міг знаходити тексти зі схожим змістом.","also":["ембединги","ембедингу","ембедингів","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Векторна база даних","text":"База даних, створена для пошуку за такими списками чисел (ембедингами), щоб знаходити матеріали зі схожим змістом.","also":["векторні бази даних","векторної бази даних","векторне сховище","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Спільний спосіб підключати інструменти та джерела даних до ШІ-застосунків, щоб ШІ міг ними користуватися.","also":["MCP","протокол контексту моделі","протоколу контексту моделі"]},{"id":"temperature","g":"ai","word":"Температура","text":"Налаштування того, наскільки сміливими будуть відповіді ШІ. Низька дає рівніші й передбачуваніші відповіді, висока — різноманітніші. Ні те, ні інше не гарантує, що він завжди правий.","also":["температури","температура моделі","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Мультимодальність","text":"Уміння працювати з кількома видами інформації, наприклад з текстом, картинками і звуком.","also":["мультимодальний","мультимодальна","мультимодальності","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Оцінювання (eval)","text":"Запланована перевірка того, наскільки добре ШІ справляється з обраними прикладами, щоб порівнювати моделі чи промпти.","also":["евал","евали","оцінювання моделі","eval","evals","evaluation"]},{"id":"bias","g":"ai","word":"Упередженість","text":"Коли ШІ (або людина) несправедливо схиляється в один бік, часто через те, на чому навчався.","also":["упередженості","упереджений","зміщення","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Відповідальний ШІ","text":"Використання ШІ чесно, безпечно й справедливо, коли за результати досі відповідають люди.","also":["відповідального ШІ","етичний ШІ","етичного ШІ","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Ін'єкція промпту","text":"Трюк, коли приховані вказівки у вебсторінці чи файлі намагаються змусити ШІ зробити те, чого його користувач не просив.","also":["ін'єкції промпту","промпт-ін'єкція","промпт-ін'єкції","prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Ліміт запитів","text":"Обмеження на те, скільки запитів можна надіслати службі за певний час. Перевищиш його — доведеться зачекати.","also":["ліміти запитів","ліміту запитів","рейт-ліміт","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Ліміт використання","text":"Скільки ШІ-роботи дозволяє твій тариф за період; після цього вона призупиняється або коштує дорожче.","also":["ліміти використання","ліміту використання","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Вайб-кодинг","text":"Створення програм переважно так: ти описуєш ШІ, чого хочеш, а він пише код.","also":["вайбкодинг","вайб-кодингу","vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Бюджет","text":"Сума грошей, відкладена на щось.","also":["бюджети","бюджету","бюджетів","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Оцінка вартості","text":"Приблизна здогадка, скільки щось коштуватиме, ще до початку.","also":["оцінки вартості","кошторис","кошторису","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Повернення інвестицій (ROI)","text":"Скільки ти отримуєш порівняно з тим, скільки вкладено. Якщо результат додатний, воно того варте.","also":["ROI","окупність","окупності","повернення інвестицій"]},{"id":"tco","g":"money","word":"Сукупна вартість володіння (TCO)","text":"Усе, чого щось справді коштує за весь час життя, а не лише ціна покупки: експлуатація, підтримка, оновлення і, нарешті, виведення з роботи.","also":["TCO","сукупної вартості володіння","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx та OpEx","text":"CapEx — гроші, витрачені одразу на те, що залишається в тебе; OpEx — постійні витрати, наприклад щомісячні рахунки.","also":["CapEx","OpEx","капітальні витрати","капітальних витрат","операційні витрати","операційних витрат","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Підписка","text":"Регулярна оплата, зазвичай раз на місяць чи рік, щоб і далі чимось користуватися.","also":["підписки","підписку","підписок","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"ПЗ як послуга (SaaS)","text":"Програма, якою ти користуєшся онлайн і платиш за неї підпискою, а запускає її для тебе розробник.","also":["SaaS","софт як сервіс","ПЗ як послуга"]},{"id":"payg","g":"money","word":"Оплата за фактом використання","text":"Платиш лише за те, чим користуєшся, як за хмарні обчислення чи ШІ-токени.","also":["оплата за використання","оплати за фактом","pay as you go","pay-as-you-go","usage-based pricing","плати за використання"]},{"id":"overage","g":"money","word":"Перевищення ліміту","text":"Використання понад те, що включає твій тариф; за нього можуть узяти додаткову плату.","also":["перевитрата","перевитрати","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Сповіщення про витрати","text":"Повідомлення, коли витрати чи використання досягають обраного тобою рівня. Воно попереджає, але не завжди зупиняє подальші списання.","also":["сповіщення про витрати","сповіщень про витрати","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Безкоштовний рівень","text":"Безкоштовний рівень платної послуги, з обмеженнями. Зручно для початку.","also":["безкоштовний тариф","безкоштовного тарифу","безкоштовного рівня","free tier","free plan"]},{"id":"pricing","g":"money","word":"Тарифний план","text":"Різні пакети, які продає послуга, у кожного своя ціна й свої обмеження.","also":["тарифні плани","тарифного плану","тариф","тарифу","тарифи","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Ліцензія","text":"Правила того, як можна використовувати, копіювати, змінювати чи поширювати те, що зробив хтось інший: програму, шрифти або картинки.","also":["ліцензії","ліцензію","ліцензій","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Відкритий вихідний код (open source)","text":"Програми, код яких будь-хто може читати, використовувати і часто змінювати безкоштовно, за правилами їхньої ліцензії.","also":["опенсорс","опенсорсу","відкритий код","відкритого коду","open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Ліцензія відкритого коду","text":"Правила, що йдуть із відкритим кодом. Одні дозволяють майже все (як MIT), інші просять ділитися і твоїми змінами (як GPL).","also":["ліцензії відкритого коду","ліцензію відкритого коду","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Пропрієтарне ПЗ","text":"Належить компанії, і його не можна вільно копіювати чи змінювати. Протилежність відкритому коду.","also":["пропрієтарний","пропрієтарне","пропрієтарного ПЗ","закрите ПЗ","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Авторське право","text":"Право автора за законом вирішувати, хто копіює його роботу, зокрема код і тексти.","also":["авторського права","авторські права","копірайт","copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Інтелектуальна власність (IP)","text":"Ідеї та витвори, які закон вважає чиєюсь власністю: код, дизайн, назви й логотипи.","also":["IP","intellectual property","інтелектуальна власність","інтелектуальної власності"]},{"id":"tos","g":"money","word":"Умови користування","text":"Правила, з якими ти погоджуєшся, коли користуєшся послугою.","also":["умов користування","угода користувача","угоди користувача","правила користування","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Договір","text":"Письмова угода між двома сторонами, яку підтримує закон.","also":["контракт","договори","договору","договорів","контракти","контракту","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Технічне завдання (SOW)","text":"Документ, у якому точно описано, яка робота буде зроблена, до якого терміну і за яку ціну.","also":["SOW","statement of work","ТЗ","технічного завдання"]},{"id":"fixedprice","g":"money","word":"Фіксована ціна","text":"Погоджена ціна за всю роботу, як би довго вона не тривала.","also":["фіксованої ціни","фіксована вартість","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Оплата за витратами (Time and Materials)","text":"Платиш за справді відпрацьовані години та справді використані матеріали, а не за наперед призначену ціну.","also":["T&M","time and materials","оплата за годинами","оплати за витратами"]},{"id":"invoice","g":"money","word":"Рахунок","text":"Документ, у якому просять оплатити виконану роботу чи поставлений товар.","also":["рахунки","рахунку","рахунків","рахунок-фактура","інвойс","інвойси","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Прив'язка до постачальника (vendor lock-in)","text":"Коли піти від постачальника так важко чи дорого, що ти застряєш у нього.","also":["лок-ін","прив'язки до постачальника","залежність від постачальника","vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Закупівлі","text":"Процес вибору постачальників і купівлі в них.","also":["закупівля","закупівель","закупівлі","procurement"]},{"id":"servicecredit","g":"money","word":"Сервісний кредит","text":"Гроші назад або знижка, які ти отримуєш, коли постачальник не виконує SLA.","also":["сервісні кредити","сервісного кредиту","компенсація за SLA","service credit","service credits"]}]}};
